function emptyDatabase(){
 let x={};IMPERIO_ARRAY_COLLECTIONS.forEach(k=>x[k]=[]);
 x.commissionSettings={discountsReduceBase:true,directPaymentReducesSettlement:true,comboAllocation:'proportional'};
 x.reportSettings={};x.schemaVersion=0;x.schemaMigratedAt='';
 x.storageMeta={dataMode:'real',createdAt:new Date().toISOString(),storageSafetyVersion:1};
 return x
}
function ensureDatabaseShape(x){
 if(!x||typeof x!=='object'||Array.isArray(x))throw new Error('Estrutura do banco inválida');
 IMPERIO_ARRAY_COLLECTIONS.forEach(k=>{if(!Array.isArray(x[k]))x[k]=[]});
 if(!x.storageMeta||typeof x.storageMeta!=='object'||Array.isArray(x.storageMeta))x.storageMeta={dataMode:'real'};
 if(!x.storageMeta.dataMode)x.storageMeta.dataMode='real';
 if(!Array.isArray(x.migrationHistory))x.migrationHistory=[];
 return x
}
function load(){
 let raw=null;
 try{raw=localStorage.getItem(IMPERIO_STORAGE_KEY)}catch(e){storageState.recoveryMode=true;storageState.readOnly=true;storageState.loadError=`Falha ao acessar armazenamento: ${e?.message||e}`;return emptyDatabase()}
 if(raw===null||raw===''){
  // Banco novo começa vazio. O seed demonstrativo permanece apenas no código legado e nunca é gravado automaticamente.
  let fresh=emptyDatabase();storageState.lastPersistedSerialized=null;return fresh
 }
 storageState.hadStoredDatabase=true;storageState.lastPersistedSerialized=raw;
 try{
  let parsed=JSON.parse(raw);return ensureDatabaseShape(parsed)
 }catch(e){
  // O valor original permanece intocado na chave principal. Nenhum seed substitui o conteúdo corrompido.
  storageState.recoveryMode=true;storageState.readOnly=true;storageState.rawCorruptedData=raw;storageState.loadError=`JSON/estrutura inválida: ${e?.message||e}`;
  return emptyDatabase()
 }
}
