function timeToMin(t='00:00'){let [h,m]=String(t).split(':').map(Number);return (h||0)*60+(m||0)}
function minToTime(v){v=Math.max(0,Math.min(1439,Math.round(v)));return String(Math.floor(v/60)).padStart(2,'0')+':'+String(v%60).padStart(2,'0')}
function addMinutesTime(t,m){return minToTime(timeToMin(t)+Number(m||0))}
function localDateISO(d=new Date()){let y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}
function addDaysISO(iso,delta){let [y,m,d]=iso.split('-').map(Number),x=new Date(y,m-1,d,12);x.setDate(x.getDate()+delta);return localDateISO(x)}
function agendaDateText(iso){let [y,m,d]=iso.split('-').map(Number),x=new Date(y,m-1,d,12);return x.toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'long',year:'numeric'})}
function normalizeBooking(b){
 if(!b.date){let _d=b.createdAt?new Date(b.createdAt):new Date();b.date=Number.isNaN(_d.getTime())?localDateISO():localDateISO(_d);b.dateInferred=true}
 if(!Array.isArray(b.items)||!b.items.length){let srv=db.services.find(s=>s.name===b.service);b.items=[{serviceId:srv?.id||'',service:b.service||'',pro:b.pro||'',time:b.time||'09:00',duration:srv?.duration||30,price:srv?.price||0}]}
 b.items.forEach(it=>{let srv=it.serviceId?db.services.find(s=>s.id===it.serviceId):db.services.find(s=>s.name===it.service);if(!it.serviceId&&srv)it.serviceId=srv.id;if(!it.service&&srv)it.service=srv.name;if(!it.duration)it.duration=srv?.duration||30;if(it.price===undefined||it.price===null)it.price=srv?.price||0;if(it.preference===undefined)it.preference=false;if(it.forceFit===undefined)it.forceFit=false});
 b.pro=b.items[0]?.pro||b.pro||'';b.time=b.items[0]?.time||b.time||'';b.service=b.items[0]?.service||b.service||'';return b
}
