function eligiblePros(serviceId,unitId){return db.pros.filter(p=>p.active&&p.units.includes(unitId)&&professionalCanDo(p.id,serviceId))}
function itemDuration(it){return Number(it.duration||db.services.find(s=>s.id===it.serviceId)?.duration||30)}
function flatAppointments(unitId,date){let out=[];(db.bookings||[]).filter(b=>b.unit===unitId&&b.date===date&&b.status!=='Cancelado').forEach(b=>{normalizeBooking(b);b.items.forEach((it,index)=>out.push({booking:b,item:it,index}))});return out}
function agendaConflicts(bookingId,itemIndex,proId,date,time,duration,unitId=null){let a=timeToMin(time),z=a+Number(duration||30);return flatAppointments(unitId||unitPicker.value||'',date).filter(x=>{if(x.booking.id===bookingId&&x.index===itemIndex)return false;if(x.booking.status==='Faltou'||x.booking.status==='Cancelado')return false;if(x.item.pro!==proId)return false;let s=timeToMin(x.item.time),e=s+itemDuration(x.item);return a<e&&z>s})}
function agendaHasConflict(bookingId,itemIndex,proId,date,time,duration,unitId=null){return agendaConflicts(bookingId,itemIndex,proId,date,time,duration,unitId).length>0}
function agendaConflictSummary(conflicts=[]){let seen=new Set(),parts=[];for(const x of conflicts){let key=x.booking.id+'-'+x.index;if(seen.has(key))continue;seen.add(key);let end=minToTime(timeToMin(x.item.time)+itemDuration(x.item));parts.push(`${x.booking.client||'Cliente'} — ${x.item.service||'Serviço'} (${x.item.time}–${end})`)}return parts.join('\n')}
function signalForBooking(id){return (db.clientCreditMovements||[]).filter(x=>x.appointmentId===id&&x.type==='Sinal recebido'&&Number(x.amount)>0).reduce((a,x)=>a+Number(x.amount),0)}
function bookingStatusClass(status=''){return ({'Agendado':'status-scheduled','Aguardando confirmação':'status-awaiting','Confirmado':'status-confirmed','Em atendimento':'status-inservice','Concluído':'status-completed','Faltou':'status-noshow','Bloqueado':'status-blocked'})[status]||'status-scheduled'}
function cancelAgendaAddServiceMode(){agendaAddServiceContext=null;renderAgenda();toast('Inclusão de serviço cancelada')}
