function agendaDrop(ev,proId,time){ev.preventDefault();ev.stopPropagation();document.querySelector('.agenda')?.classList.remove('agenda-drag-active');document.querySelectorAll('.drop-target').forEach(x=>x.classList.remove('drop-target'));let data;try{data=JSON.parse(ev.dataTransfer.getData('text/plain'))}catch{return}let b=db.bookings.find(x=>x.id===data.bid);if(!b)return;normalizeBooking(b);let it=b.items[data.idx];if(!it)return;if(b.status==='Bloqueado'){moveBlockByDrag(b,it,proId,time);return}if(!professionalCanDo(proId,it.serviceId)){toast('Esta profissional não executa este serviço');return}let targetPro=db.pros.find(p=>p.id===proId)?.name||proId;if(it.preference&&proId!==it.pro&&!confirm(`Este atendimento está marcado como preferência de ${db.pros.find(p=>p.id===it.pro)?.name||'outra profissional'}. Deseja mover para ${targetPro} mesmo assim?`))return;let conflicts=agendaConflicts(b.id,data.idx,proId,b.date,time,itemDuration(it),b.unit);let blocked=conflicts.filter(x=>x.booking.status==='Bloqueado');if(blocked.length){toast('Este horário possui um bloqueio. Remova ou edite o bloqueio antes de mover o atendimento.');return}if(conflicts.length&&!it.forceFit){let detail=agendaConflictSummary(conflicts);let ok=confirm(`Existe conflito neste horário com:

${detail}

Deseja forçar o encaixe de ${b.client||'cliente'} às ${time} com ${targetPro}?`);if(!ok)return;it.forceFit=true}let oldPro=it.pro,oldTime=it.time;it.pro=proId;it.time=time;b.pro=b.items[0].pro;b.time=b.items[0].time;let hist=(db.clientAppointments||[]).find(x=>x.id===b.id);if(hist&&data.idx===0){hist.time=time;hist.professional=targetPro;hist.date=b.date}save();renderAgenda();toast(`Agendamento movido de ${db.pros.find(p=>p.id===oldPro)?.name||oldPro} ${oldTime} para ${targetPro} ${time}${conflicts.length?' · encaixe forçado':''}`)}
function moveBlockByDrag(b,it,proId,time){let oldPro=it.pro,oldTime=it.time,targetPro=db.pros.find(p=>p.id===proId)?.name||proId,newTime=b.blockAllDay?'09:00':time,dur=itemDuration(it),conflicts=agendaConflicts(b.id,0,proId,b.date,newTime,dur,b.unit).filter(x=>x.booking.status!=='Faltou');if(conflicts.length){let detail=agendaConflictSummary(conflicts);if(!confirm(`O bloqueio ficará sobre ${conflicts.length} compromisso(s):

${detail}

Deseja mover o bloqueio mesmo assim?`))return}if(b.blockSeriesId&&!confirm('Este bloqueio faz parte de uma repetição. Ao arrastar, somente esta ocorrência será movida. Deseja continuar?'))return;it.pro=proId;it.time=newTime;b.pro=proId;b.time=newTime;if(b.blockSeriesId)b.blockException=true;save();renderAgenda();toast(`Bloqueio movido de ${db.pros.find(p=>p.id===oldPro)?.name||oldPro} ${oldTime} para ${targetPro} ${b.blockAllDay?'dia inteiro':newTime} ✓`)}
function digits(v=''){return String(v).replace(/\D/g,'')}
function normName(v=''){return String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase()}
function cepLookup(cep){const d=digits(cep);const demo={'32340000':{neighborhood:'Eldorado',city:'Contagem'},'32040000':{neighborhood:'Centro',city:'Contagem'},'32110000':{neighborhood:'Cabral',city:'Contagem'},'32280000':{neighborhood:'Riacho das Pedras',city:'Contagem'},'32041000':{neighborhood:'Inconfidentes',city:'Contagem'},'30130010':{neighborhood:'Funcionários',city:'Belo Horizonte'}};return demo[d]||null}
function sourceOptions(selected=''){return db.acquisitionSources.filter(x=>x.active||x.name===selected).map(x=>`<option value="${escapeAttr(x.name)}" ${x.name===selected?'selected':''}>${escapeHtml(x.name)}</option>`).join('')}
