function agendaLaneLayout(aps,proId){
 const arr=aps.filter(x=>x.item.pro===proId).map(x=>({x,start:timeToMin(x.item.time),end:timeToMin(x.item.time)+itemDuration(x.item)})).sort((a,b)=>a.start-b.start||a.end-b.end);
 const map={};let i=0;
 while(i<arr.length){let group=[arr[i]],groupEnd=arr[i].end,j=i+1;while(j<arr.length&&arr[j].start<groupEnd){group.push(arr[j]);groupEnd=Math.max(groupEnd,arr[j].end);j++}
  let laneEnds=[],placed=[];for(const it of group){let lane=laneEnds.findIndex(e=>e<=it.start);if(lane<0)lane=laneEnds.length;laneEnds[lane]=it.end;placed.push([it,lane])}
  const count=Math.max(1,laneEnds.length);for(const [it,lane] of placed)map[it.x.booking.id+':'+it.x.index]={lane,count};i=j
 }
 return map
}
function blockWeekdayFromISO(iso){let [y,m,d]=String(iso).split('-').map(Number);return new Date(y,m-1,d,12).getDay()}
function blockDefaultUntil(iso){let [y,m,d]=String(iso).split('-').map(Number),x=new Date(y,m-1,d,12);x.setMonth(x.getMonth()+3);return localDateISO(x)}
function blockDurationMinutes(prefix='blk'){let all=!!document.getElementById(prefix+'AllDay')?.checked;if(all)return 12*60;let h=Math.max(0,Number(document.getElementById(prefix+'Hours')?.value||0)),m=Math.max(0,Number(document.getElementById(prefix+'Minutes')?.value||0));return h*60+m}
function syncBlockDurationUI(prefix='blk'){let all=!!document.getElementById(prefix+'AllDay')?.checked,time=document.getElementById(prefix+'Time'),box=document.getElementById(prefix+'DurationFields');if(time){time.disabled=all;if(all)time.value='09:00'}if(box)box.style.opacity=all?'.45':'1';updateBlockRepeatPreview()}
function toggleBlockRepeat(){let on=!!document.getElementById('blkRepeat')?.checked,box=document.getElementById('blkRepeatOptions');if(box)box.classList.toggle('hidden',!on);if(on)syncBlockRepeatUI()}
function syncBlockRepeatUI(){let freq=document.getElementById('blkFreq')?.value||'weekly',weekly=document.getElementById('blkWeeklyOptions'),intervalWrap=document.getElementById('blkIntervalWrap');if(weekly)weekly.classList.toggle('hidden',freq!=='weekly');if(intervalWrap)intervalWrap.classList.toggle('hidden',freq==='weekdays');updateBlockRepeatPreview()}
function setDefaultBlockWeekday(){let d=blockWeekdayFromISO(document.getElementById('blkDate')?.value||agendaDate);document.querySelectorAll('.blk-weekday').forEach(x=>x.checked=Number(x.value)===d);updateBlockRepeatPreview()}
function selectedBlockWeekdays(){return [...document.querySelectorAll('.blk-weekday:checked')].map(x=>Number(x.value))}
function blockRepeatText(){let start=document.getElementById('blkDate')?.value||agendaDate,time=document.getElementById('blkTime')?.value||'12:00',dur=blockDurationMinutes('blk'),all=!!document.getElementById('blkAllDay')?.checked,freq=document.getElementById('blkFreq')?.value||'weekly',interval=Math.max(1,Number(document.getElementById('blkInterval')?.value||1)),until=document.getElementById('blkUntil')?.value||'',end=addMinutesTime(time,dur);let windowText=all?'dia inteiro':`${time}–${end}`;if(!document.getElementById('blkRepeat')?.checked)return `Bloqueio único · ${formatDateBR(start)} · ${windowText}`;let label='';if(freq==='weekly'){let names=['domingo','segunda','terça','quarta','quinta','sexta','sábado'],days=selectedBlockWeekdays();label=(interval===1?'Toda semana':'A cada '+interval+' semanas')+(days.length?' · '+days.map(d=>names[d]).join(', '):'')}else if(freq==='daily')label=interval===1?'Todos os dias':'A cada '+interval+' dias';else label='De segunda a sexta';return `${label} · ${windowText}${until?' · até '+formatDateBR(until):''}`}
function updateBlockRepeatPreview(){let el=document.getElementById('blkRepeatPreview');if(el)el.textContent=blockRepeatText()}
function generateBlockDates(start,freq,interval,weekdays,until){let out=[],startD=new Date(start+'T12:00:00'),endD=new Date(until+'T12:00:00'),max=370;if(endD<startD)return out;for(let i=0,cur=new Date(startD);cur<=endD&&i<max;cur.setDate(cur.getDate()+1),i++){let iso=localDateISO(cur),delta=Math.floor((cur-startD)/86400000),ok=false;if(freq==='daily')ok=delta%Math.max(1,interval)===0;else if(freq==='weekdays')ok=cur.getDay()>=1&&cur.getDay()<=5;else{let week=Math.floor(delta/7);ok=week%Math.max(1,interval)===0&&weekdays.includes(cur.getDay())}if(ok)out.push(iso)}return out}
function blockDurationFields(prefix='blk',dur=60,allDay=false){let h=Math.floor(Number(dur||60)/60),m=Number(dur||60)%60;return `<label class="block-all-day"><input id="${prefix}AllDay" type="checkbox" ${allDay?'checked':''} onchange="syncBlockDurationUI('${prefix}')"> Bloquear o dia inteiro</label><div id="${prefix}DurationFields" class="block-duration-grid" style="${allDay?'opacity:.45':''}"><div class="field"><label>Horas</label><input id="${prefix}Hours" type="number" min="0" max="12" step="1" value="${h}" oninput="updateBlockRepeatPreview()"></div><div class="field"><label>Minutos</label><input id="${prefix}Minutes" type="number" min="0" max="59" step="5" value="${m}" oninput="updateBlockRepeatPreview()"></div></div>`}
function openBlockTime(){
 const uid=unitPicker.value||'',pros=db.pros.filter(p=>p.active&&p.units.includes(uid)),until=blockDefaultUntil(agendaDate),weekday=blockWeekdayFromISO(agendaDate);
 modal('Bloquear horário',`<div class="form-grid"><div class="field"><label>Profissional *</label><select id="blkPro">${pros.map(p=>`<option value="${p.id}">${escapeHtml(p.name)}</option>`).join('')}</select></div><div class="field"><label>Data inicial *</label><input id="blkDate" type="date" value="${agendaDate}" onchange="setDefaultBlockWeekday();updateBlockRepeatPreview()"></div><div class="field"><label>Início *</label><input id="blkTime" type="time" step="300" value="12:00" oninput="updateBlockRepeatPreview()"></div><div class="field"><label>Duração personalizada</label>${blockDurationFields('blk',60,false)}</div><div class="field full"><label>Motivo</label><input id="blkReason" placeholder="Ex.: Almoço, compromisso, treinamento"></div><div class="block-repeat-box"><label class="check" style="margin:0"><input id="blkRepeat" type="checkbox" onchange="toggleBlockRepeat()"> <b>Repetir este bloqueio</b></label><div class="help">Útil para almoço, faculdade, reunião ou qualquer indisponibilidade recorrente.</div><div id="blkRepeatOptions" class="hidden"><div class="block-repeat-row"><div class="field"><label>Frequência</label><select id="blkFreq" onchange="syncBlockRepeatUI()"><option value="weekly">Semanal</option><option value="daily">Diariamente</option><option value="weekdays">Dias úteis (seg–sex)</option></select></div><div class="field" id="blkIntervalWrap"><label>Repetir a cada</label><select id="blkInterval" onchange="updateBlockRepeatPreview()"><option value="1">1</option><option value="2">2</option><option value="3">3</option><option value="4">4</option></select></div></div><div id="blkWeeklyOptions"><div class="field"><label>Dias da semana</label><div class="block-weekdays">${[['Dom',0],['Seg',1],['Ter',2],['Qua',3],['Qui',4],['Sex',5],['Sáb',6]].map(([n,v])=>`<label class="weekday-chip"><input class="blk-weekday" type="checkbox" value="${v}" ${v===weekday?'checked':''} onchange="updateBlockRepeatPreview()">${n}</label>`).join('')}</div></div></div><div class="field" style="margin-top:10px"><label>Repetir até</label><input id="blkUntil" type="date" value="${until}" onchange="updateBlockRepeatPreview()"></div></div><div id="blkRepeatPreview" class="block-repeat-preview">Bloqueio único · ${formatDateBR(agendaDate)} · 12:00–13:00</div></div></div>`,`<button class="btn btn-ghost" onclick="closeModal()">Cancelar</button><button class="btn btn-primary" onclick="saveBlockTime()">Bloquear horário</button>`);setTimeout(()=>{syncBlockDurationUI('blk');updateBlockRepeatPreview()},0)
}
function saveBlockTime(){let uid=unitPicker.value||'',pro=blkPro.value,date=blkDate.value,time=blkTime.value,dur=blockDurationMinutes('blk'),allDay=!!document.getElementById('blkAllDay')?.checked,reason=blkReason.value.trim()||'Horário bloqueado',repeat=!!document.getElementById('blkRepeat')?.checked;if(allDay)time='09:00';if(!pro||!date||!time){toast('Preencha profissional, data e horário');return}if(!dur||dur<5){toast('Informe uma duração maior que zero');return}if(dur>12*60){toast('A duração máxima nesta prévia é de 12 horas');return}let dates=[date],recurrence=null;if(repeat){let freq=blkFreq.value,interval=Math.max(1,Number(blkInterval?.value||1)),weekdays=selectedBlockWeekdays(),until=blkUntil.value;if(!until){toast('Informe até quando o bloqueio deve se repetir');return}if(freq==='weekly'&&!weekdays.length){toast('Selecione pelo menos um dia da semana');return}dates=generateBlockDates(date,freq,interval,weekdays,until);if(!dates.length){toast('Nenhuma ocorrência foi encontrada nesse período');return}recurrence={freq,interval,weekdays,until,label:blockRepeatText()}}let conflictCount=0;for(const d of dates)conflictCount+=agendaConflicts('',-1,pro,d,time,dur,uid).filter(x=>x.booking.status!=='Faltou').length;if(conflictCount&&!confirm(`A série alcança ${conflictCount} atendimento(s) existente(s). Deseja criar o(s) bloqueio(s) mesmo assim?`))return;let seriesId=repeat?'bs'+Date.now():'';dates.forEach((d,i)=>{let id='blk'+Date.now()+'_'+i;db.bookings.push({id,unit:uid,date:d,client:'Bloqueado',status:'Bloqueado',origin:'Interno',notes:reason,blockAllDay:allDay,blockSeriesId:seriesId||null,blockRecurrence:recurrence,items:[{serviceId:'',service:reason,pro,time,duration:dur,price:0,preference:false,forceFit:false}]})});save();closeModal();agendaDate=date;renderAgenda();toast(repeat?`${dates.length} bloqueios recorrentes criados ✓`:'Horário bloqueado ✓')}
