 let conflicts=agendaConflicts('',-1,proId,date,start,dur,unitId),blocked=conflicts.filter(x=>x.booking.status==='Bloqueado'),occupied=conflicts.filter(x=>x.booking.status!=='Bloqueado');
 if(blocked.length)return null;
 let selfOverlap=assigned.some(x=>x.proId===proId&&a<x.endMin&&z>x.startMin),isFit=!!(occupied.length||selfOverlap);
