async function copyAvailabilityResults(){
 let text=availabilityCopyText();if(!text){toast('Faça uma busca primeiro');return}
 try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(text);else throw new Error('clipboard')}catch(e){let ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove()}
 toast('Horários copiados para colar no WhatsApp ✓');
}
function useAvailabilityResult(i){
 let r=availabilityFinderResults[i];if(!r)return;unitPicker.value=r.unitId;agendaDate=r.date;closeModal();renderAgenda();
 window.resDraft={proId:r.assignments[0]?.proId||'',time:r.start,clientId:'',clientSearch:'',date:r.date,status:'Agendado',items:r.assignments.map(a=>{let srv=db.services.find(s=>s.id===a.serviceId);return {serviceId:a.serviceId,service:srv?.name||'',pro:a.proId,time:a.start,duration:a.duration,price:availabilityServicePrice(a.serviceId,a.proId),preference:false,forceFit:!!a.forceFit}})};
 // A busca fecha antes de abrir a reserva; preferência é mantida por serviço a partir do profissional escolhido na busca.
 let specs=window._lastAvailabilitySpecs||[];
 resDraft.items.forEach(it=>it.preference=specs.some(sp=>sp.serviceId===it.serviceId&&sp.preferredPro===it.pro));
 renderReservationModal();
}

function openOpenCommands(){
 let uid=unitPicker.value||'';let rows=(db.clientCommands||[]).filter(c=>c.unitId===uid&&c.date===agendaDate&&c.status==='Aberta');
 let inService=(db.bookings||[]).filter(b=>b.unit===uid&&b.date===agendaDate&&b.status==='Em atendimento'&&!rows.some(c=>(c.bookingIds||[]).includes(b.id)));
 let body='';
 if(rows.length){body+=`<div class="command-open-list table-card"><table class="table"><thead><tr><th>Cliente</th><th>Aberta</th><th>Itens</th><th>Total atual</th><th></th></tr></thead><tbody>${rows.map(c=>{normalizeCommand(c);let cli=db.clients.find(x=>x.id===c.clientId);return `<tr><td><b>${escapeHtml(cli?.name||c.clientName||'Cliente')}</b></td><td>${escapeHtml(c.openedAt?formatTimeLocal(c.openedAt):'—')}</td><td>${c.lines.length}</td><td><b>${money(commandGrossTotal(c))}</b></td><td><button class="btn btn-primary btn-sm" onclick="openCommand('${c.id}')">Abrir comanda</button></td></tr>`}).join('')}</tbody></table></div>`}
 if(inService.length){body+=`<div class="inline-note" style="margin-top:${rows.length?'12':'0'}px"><b>${inService.length} atendimento(s) em andamento sem comanda.</b> Você pode abrir a comanda agora.</div><div class="table-card" style="margin-top:8px"><table class="table"><tbody>${inService.map(b=>`<tr><td><b>${escapeHtml(b.client||'Cliente')}</b></td><td>${escapeHtml(b.items?.[0]?.time||'')}</td><td><button class="btn btn-ghost btn-sm" onclick="openCommandFromBooking('${b.id}')">Abrir comanda</button></td></tr>`).join('')}</tbody></table></div>`}
 if(!rows.length&&!inService.length)body=`<div class="command-empty"><b>Nenhuma comanda aberta nesta unidade/data.</b><div style="margin-top:5px">Abra uma reserva da Agenda e clique em <b>Abrir comanda</b> quando a cliente chegar.</div></div>`;
 modal(`Comandas abertas · ${rows.length}`,body,`<button class="btn btn-ghost" onclick="closeModal()">Fechar</button>`);setTimeout(()=>document.querySelector('#modalHost .modal')?.classList.add('modal-wide'),0)
}
function renderAgenda(){
 subbar.innerHTML='Agenda &nbsp;·&nbsp; Agendamento Online &nbsp;·&nbsp; Bloqueios &nbsp;·&nbsp; Capacidade';
 const uid=unitPicker.value||'';const ps=db.pros.filter(p=>p.active&&p.units.includes(uid));
 let times=[];for(let m=9*60;m<21*60;m+=15)times.push(minToTime(m));let aps=flatAppointments(uid,agendaDate);
 const laneByPro={};ps.forEach(p=>laneByPro[p.id]=agendaLaneLayout(aps,p.id));
 let now=new Date(),currentKey=agendaDate===localDateISO(now)?minToTime(Math.floor((now.getHours()*60+now.getMinutes())/15)*15):'';
 let cells=`<div class="head"></div>${ps.map(p=>`<div class="head pro-head" style="background:${escapeAttr(p.agendaColor||defaultAgendaColor(p))}"><b>${escapeHtml(p.publicName||p.name)}</b><small>${escapeHtml(p.specialty||'')}</small></div>`).join('')}`;
 for(const time of times){let cur=time===currentKey?' current-time':'';cells+=`<div class="time${cur}">${time}</div>`;for(const p of ps){let starts=aps.filter(x=>x.item.pro===p.id&&x.item.time===time);cells+=`<div class="slot${cur}" data-pro="${p.id}" data-time="${time}" onclick="agendaSlotClick('${p.id}','${time}')" ondragover="agendaAllowDrop(event)" ondragleave="agendaLeaveDrop(event)" ondrop="event.stopPropagation();agendaDrop(event,'${p.id}','${time}')">${starts.map(x=>{let b=x.booking,it=x.item,dur=itemDuration(it),h=Math.max(18,Math.round(dur/15*20)-2),sig=signalForBooking(b.id),cls=bookingStatusClass(b.status),lay=laneByPro[p.id]?.[b.id+':'+x.index]||{lane:0,count:1},left=lay.lane*(100/lay.count),width=100/lay.count;return `<div class="booking ${cls} ${b.status==='Bloqueado'?'blocked':''}" style="height:${h}px;left:calc(${left}% + 2px);width:calc(${width}% - 4px);right:auto" draggable="true" ondragstart="agendaDrag(event,'${b.id}',${x.index})" ondragend="agendaDragEnd(event)" onclick="event.stopPropagation();${b.status==='Bloqueado'?`openBlockEditor('${b.id}')`:`openExistingBooking('${b.id}')`}"><strong>${escapeHtml(b.client||'Cliente')}</strong>${escapeHtml(it.service||'')}${it.preference?`<span class="preference-tag" title="Preferência da profissional">★</span>`:''}${it.forceFit?`<span class="fit-tag" title="Encaixe forçado">↔</span>`:''}${sig?`<span class="signal-tag" title="Sinal pago: ${money(sig)}">Sinal</span>`:''}${b.blockSeriesId?`<span class="repeat-tag">↻</span>`:''}${b.blockAllDay?`<span class="all-day-tag">Dia inteiro</span>`:''}</div>`}).join('')}</div>`}}
 const addMode=agendaAddServiceContext?`<div class="agenda-add-mode"><div><b>Adicionar serviço para ${escapeHtml(agendaAddServiceContext.clientName)}</b><div class="muted">Clique no horário e na profissional desejados. Depois selecione o serviço.</div></div><div class="spacer"></div><button class="btn btn-ghost btn-sm" onclick="cancelAgendaAddServiceMode()">Cancelar</button></div>`:'';
 const legend=`<div class="agenda-legend"><span class="legend-item"><i class="legend-dot" style="background:#f1eaf3"></i>Agendado</span><span class="legend-item"><i class="legend-dot legend-awaiting"></i>Aguardando</span><span class="legend-item"><i class="legend-dot legend-confirmed"></i>Confirmado</span><span class="legend-item"><i class="legend-dot legend-inservice"></i>Na loja</span><span class="legend-item"><i class="legend-dot legend-completed"></i>Finalizado</span><span class="legend-item"><i class="legend-dot legend-noshow"></i>Faltou</span></div>`;
 const openCount=(db.clientCommands||[]).filter(c=>c.unitId===uid&&c.date===agendaDate&&c.status==='Aberta').length;
 adminPage.innerHTML=`<div class="page-head"><div><h1>Agenda</h1><div class="agenda-date-title">${escapeHtml(agendaDateText(agendaDate))}</div></div><div class="agenda-date-controls"><button class="btn btn-ghost btn-sm" onclick="agendaGo(-1)">‹</button><input type="date" value="${agendaDate}" onchange="agendaPickDate(this.value)"><button class="btn btn-ghost btn-sm" onclick="agendaGo(1)">›</button></div><div class="spacer"></div><div class="client-picker"><input id="agendaClientSearch" class="search" placeholder="Buscar cliente..." oninput="agendaClientSearchResults()"><div id="agendaClientResults"></div></div><button class="btn btn-primary" onclick="openReservation('','','',agendaDate)">+ Novo</button></div>${addMode}<div class="agenda-toolbar"><button class="btn btn-soft btn-sm" onclick="agendaToday()">Hoje</button><button class="btn btn-primary btn-sm" onclick="openAvailabilityFinder()">Encontrar horário</button><button class="btn btn-ghost btn-sm" onclick="openBlockTime()">Bloquear horário</button><button class="btn btn-ghost btn-sm" onclick="openOpenCommands()">Comandas abertas <span class="cmd-badge">${openCount}</span></button><div class="toolbar-spacer"></div>${legend}</div><div class="agenda-wrap"><div class="agenda" style="grid-template-columns:68px repeat(${Math.max(ps.length,1)},minmax(150px,1fr))">${cells}</div></div>`
}
function renderClients(){subbar.textContent='Clientes · Retornos · Créditos · Pacotes · WhatsApp';adminPage.innerHTML=`<div class="page-head"><div><h1>Clientes</h1><div class="muted">Cadastro único para todas as unidades e para o agendamento online</div></div><div class="spacer"></div><input id="clientSearch" class="search" placeholder="Nome, celular, CPF, bairro ou cidade" oninput="renderClientRows()"><button class="btn btn-ghost" onclick="openSourceManager()">Como conheceu?</button><button class="btn btn-primary" onclick="openClientForm()">+ Nova cliente</button></div><div class="table-card"><table class="table"><thead><tr><th>Cliente</th><th>Celular</th><th>Bairro / Cidade</th><th>Última visita</th><th>Próximo</th><th>Origem</th><th></th></tr></thead><tbody id="clientRows"></tbody></table></div>`;renderClientRows()}
function renderClientRows(){let q=(document.getElementById('clientSearch')?.value||'').toLowerCase();let rows=db.clients.filter(c=>(c.name+' '+c.phone+' '+c.cpf+' '+c.neighborhood+' '+(c.city||'')).toLowerCase().includes(q)).map(c=>`<tr><td><b>${escapeHtml(c.name)}</b><div class="muted" style="font-size:12px">${c.birthDate?new Date(c.birthDate+'T12:00:00').toLocaleDateString('pt-BR'):''}</div></td><td>${escapeHtml(c.phone)}</td><td>${escapeHtml(c.neighborhood||'—')}<div class="muted" style="font-size:12px">${escapeHtml(c.city||'—')}</div></td><td>${c.last||'—'}</td><td>${c.next||'—'}</td><td>${escapeHtml(c.source||'—')}</td><td><button class="btn btn-ghost btn-sm" onclick="openClient('${c.id}')">Abrir</button></td></tr>`).join('');if(document.getElementById('clientRows'))clientRows.innerHTML=rows}
function contractInfo(p){
 let d=p.contractEndDate;if(!d)return {html:'<span class="contract-empty">Não informado</span>',expired:false,soon:false,days:null};
 let today=new Date();today.setHours(0,0,0,0);let end=new Date(d+'T00:00:00');let days=Math.ceil((end-today)/86400000);let br=end.toLocaleDateString('pt-BR');
 if(days<0)return {html:`<span class="contract-expired">Vencido em ${br}</span>`,expired:true,soon:false,days};
 if(days===0)return {html:`<span class="contract-expired">Vence hoje (${br})</span>`,expired:true,soon:false,days};
 if(days<=30)return {html:`<span class="contract-soon">Vence em ${days} dia${days===1?'':'s'} · ${br}</span>`,expired:false,soon:true,days};
 return {html:`<span class="contract-ok">${br}</span>`,expired:false,soon:false,days};
}
function contractAlertBanner(){
 let exp=db.pros.filter(p=>p.active&&contractInfo(p).expired),soon=db.pros.filter(p=>p.active&&contractInfo(p).soon);
 if(!exp.length&&!soon.length)return '';
 let parts=[];if(exp.length)parts.push(`<b>${exp.length}</b> contrato${exp.length>1?'s':''} vencido${exp.length>1?'s':''}`);if(soon.length)parts.push(`<b>${soon.length}</b> vencendo nos próximos 30 dias`);
 return `<div class="contract-alert"><div>🔔</div><div><strong>Contratos de profissionais</strong><div class="muted">${parts.join(' · ')}. No sistema final, esta mesma regra gera uma notificação/tarefa automática para os perfis autorizados.</div></div></div>`;
}
function renderPros(){subbar.textContent='Cadastro · Horários · Serviços · Comissões';adminPage.innerHTML=`<div class="page-head"><div><h1>Profissionais</h1><div class="muted">Cadastre, edite, publique ou desative profissionais.</div></div><div class="spacer"></div><button class="btn btn-primary" onclick="openProForm()">+ Nova profissional</button></div>${contractAlertBanner()}<div class="table-card"><table class="table"><thead><tr><th>Profissional</th><th>Especialidade</th><th>Unidades</th><th>Contrato</th><th>Site</th><th>Status</th><th></th></tr></thead><tbody>${db.pros.map(p=>`<tr><td><b>${p.name}</b></td><td>${p.specialty||'—'}</td><td>${p.units.map(id=>db.units.find(u=>u.id===id)?.name).filter(Boolean).join(', ')}</td><td>${contractInfo(p).html}</td><td>${p.show?'Sim':'Não'}</td><td class="${p.active?'status-on':'status-off'}">${p.active?'Ativa':'Inativa'}</td><td class="row-actions"><button class="btn btn-ghost btn-sm" onclick="openProForm('${p.id}')">Editar</button><button class="btn btn-danger btn-sm" onclick="togglePro('${p.id}')">${p.active?'Desativar':'Ativar'}</button></td></tr>`).join('')}</tbody></table></div>`}
function renderServices(){subbar.textContent='Categorias · Serviços · Regras de retorno';adminPage.innerHTML=`<div class="page-head"><div><h1>Serviços</h1><div class="muted">O que estiver publicado aqui aparece automaticamente no site.</div></div><div class="spacer"></div><button class="btn btn-primary" onclick="openServiceForm()">+ Novo serviço</button></div><div class="table-card"><table class="table"><thead><tr><th>Serviço</th><th>Categoria</th><th>Duração</th><th>Preço</th><th>Site</th><th>Status</th><th></th></tr></thead><tbody>${db.services.map(s=>`<tr><td><b>${s.name}</b>${s.description?`<div class="muted" style="font-size:12px;margin-top:3px;max-width:320px">${escapeHtml(s.description)}</div>`:''}</td><td>${db.categories.find(c=>c.id===s.category)?.name||'—'}</td><td>${s.duration} min</td><td>${money(s.price)}</td><td>${s.show?'Sim':'Não'}</td><td class="${s.active?'status-on':'status-off'}">${s.active?'Ativo':'Inativo'}</td><td class="row-actions"><button class="btn btn-ghost btn-sm" onclick="openServiceForm('${s.id}')">Editar</button><button class="btn btn-danger btn-sm" onclick="toggleService('${s.id}')">${s.active?'Desativar':'Ativar'}</button></td></tr>`).join('')}</tbody></table></div>`}

function cashUnitId(){let id=document.getElementById('unitPicker')?.value||'';return (db.units||[]).some(u=>u.id===id&&u.active!==false)?id:''}
function cashUnitName(uid=cashUnitId()){return db.units.find(u=>u.id===uid)?.name||'Unidade'}
function cashSessionFor(uid=cashUnitId(),date=cashDate){return (db.cashSessions||[]).filter(x=>x.unitId===uid&&x.date===date).sort((a,b)=>String(b.openedAt||'').localeCompare(String(a.openedAt||'')))[0]||null}
function cashMovementsFor(uid=cashUnitId(),date=cashDate){return (db.demoCashMovements||[]).filter(x=>x.unitId===uid&&x.date===date).sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||'')))}
function cashPhysicalAccount(uid=cashUnitId()){return (db.financialAccounts||[]).find(a=>a.unitId===uid&&a.type==='CASH')}
function cashIsPhysicalMovement(m){let a=cashPhysicalAccount(m.unitId),t=String(m.type||'');return m.paymentMethod==='Dinheiro'||(a&&m.account===a.name)||t==='Suprimento'||t.startsWith('Sangria')||t==='Vale a funcionário'}
function cashReceiptMovement(m){return Number(m.amount||0)>0&&!['Suprimento'].includes(m.type)}
function cashTotals(uid=cashUnitId(),date=cashDate){let ms=cashMovementsFor(uid,date),session=cashSessionFor(uid,date),opening=Number(session?.openingAmount||0);let receipts=ms.filter(cashReceiptMovement),received=receipts.reduce((a,m)=>a+Number(m.amount||0),0),cash=receipts.filter(m=>m.paymentMethod==='Dinheiro').reduce((a,m)=>a+Number(m.amount||0),0),pix=receipts.filter(m=>m.paymentMethod==='Pix').reduce((a,m)=>a+Number(m.amount||0),0),cards=receipts.filter(m=>String(m.paymentMethod||'').includes('Cartão')).reduce((a,m)=>a+Number(m.amount||0),0),fees=receipts.reduce((a,m)=>a+Number(m.processorFee||0),0),physicalDelta=ms.filter(cashIsPhysicalMovement).reduce((a,m)=>a+Number(m.amount||0),0),physicalExpected=opening+physicalDelta,sangrias=ms.filter(m=>Number(m.amount||0)<0&&cashIsPhysicalMovement(m)).reduce((a,m)=>a+Math.abs(Number(m.amount||0)),0),expenses=ms.filter(m=>m.cashNature==='expense').reduce((a,m)=>a+Math.abs(Number(m.amount||0)),0),advances=ms.filter(m=>m.cashNature==='employee_advance').reduce((a,m)=>a+Math.abs(Number(m.amount||0)),0),transfers=ms.filter(m=>m.cashNature==='transfer').reduce((a,m)=>a+Math.abs(Number(m.amount||0)),0),tips=(db.tipMovements||[]).filter(x=>x.unitId===uid&&x.date===date).reduce((a,x)=>a+Number(x.gross||0),0);return {ms,session,opening,received,cash,pix,cards,fees,physicalExpected,sangrias,expenses,advances,transfers,tips}}
function setCashTab(tab){cashTab=tab;renderCash()}
function cashSubnav(){return `<div class="cash-subnav"><button class="${cashTab==='current'?'active':''}" onclick="setCashTab('current')">Caixa Atual</button><button class="${cashTab==='movements'?'active':''}" onclick="setCashTab('movements')">Movimentações</button><button class="${cashTab==='closures'?'active':''}" onclick="setCashTab('closures')">Fechamentos</button></div>`}
function cashTime(m){let x=String(m.createdAt||'');return x.includes('T')?x.slice(11,16):'—'}
function cashOriginText(m){let cli=db.clients.find(c=>c.id===m.clientId);if(cli)return cli.name;if(m.employeeId){let p=db.pros.find(x=>x.id===m.employeeId);return `${p?.name||'Colaborador'}${m.note?' · '+m.note:''}`}if(m.commandId)return `Comanda #${String(m.commandId).replace(/\D/g,'').slice(-6)}`;return m.note||m.type||'Movimentação'}
function cashMovementRows(ms){return ms.map(m=>{let n=Number(m.amount||0),fee=Number(m.processorFee||0);return `<tr><td>${cashTime(m)}</td><td><b>${escapeHtml(m.type||'Movimentação')}</b></td><td>${escapeHtml(cashOriginText(m))}</td><td>${escapeHtml(m.paymentMethod||'—')}</td><td>${escapeHtml(m.account||'—')}</td><td>${fee?money(fee):'—'}</td><td class="${n<0?'cash-value-out':'cash-value-in'}">${n<0?'− ':''}${money(Math.abs(n))}</td><td>${escapeHtml(m.user||'Sistema')}</td></tr>`}).join('')||'<tr><td colspan="8" class="muted">Nenhuma movimentação neste período.</td></tr>'}
function cashMovementTable(ms){return `<div class="cash-table-wrap"><table class="cash-table"><thead><tr><th>Hora</th><th>Tipo</th><th>Cliente / origem</th><th>Forma</th><th>Conta / destino</th><th>Taxa op.</th><th>Valor</th><th>Usuário</th></tr></thead><tbody>${cashMovementRows(ms)}</tbody></table></div>`}
function renderCash(){let uid=cashUnitId(),t=cashTotals(uid,cashDate),s=t.session;subbar.innerHTML=cashSubnav();let head=`<div class="page-head"><div><h1>Caixa</h1><div class="muted">${escapeHtml(cashUnitName(uid))} · controle diário de recebimentos e caixa físico</div></div><div class="spacer"></div><input class="unit-select" type="date" value="${cashDate}" onchange="cashDate=this.value;renderCash()"></div>`;if(cashTab==='movements'){adminPage.innerHTML=head+`<div class="cash-kpis"><div class="cash-kpi emphasis"><span>Total recebido</span><b>${money(t.received)}</b></div><div class="cash-kpi"><span>Dinheiro</span><b>${money(t.cash)}</b></div><div class="cash-kpi"><span>Pix</span><b>${money(t.pix)}</b></div><div class="cash-kpi"><span>Cartões</span><b>${money(t.cards)}</b></div><div class="cash-kpi"><span>Taxas de operadora</span><b>${money(t.fees)}</b></div></div>${cashMovementTable(t.ms)}`;return}if(cashTab==='closures'){let sessions=(db.cashSessions||[]).filter(x=>x.unitId===uid).sort((a,b)=>String(b.date).localeCompare(String(a.date)));adminPage.innerHTML=head+(sessions.map(x=>`<div class="cash-history-card"><div class="cash-history-head"><b>Caixa do dia ${formatDateBR(x.date)}</b><span class="${x.status==='open'?'cash-status-open':'cash-status-closed'}">${x.status==='open'?'● Aberto':'Fechado'}</span><div class="spacer"></div><div class="cash-history-actions">${x.status==='closed'?`<button class="btn btn-soft btn-sm" onclick="copyCashClosure('${x.id}')">Copiar WhatsApp</button><button class="btn btn-ghost btn-sm" onclick="openReopenCash('${x.id}')">Reabrir</button>`:''}</div></div><div class="cash-history-meta"><span>Abertura: ${money(x.openingAmount||0)}</span><span>Esperado em dinheiro: ${x.systemExpected==null?'—':money(x.systemExpected)}</span><span>Contado: ${x.countedAmount==null?'—':money(x.countedAmount)}</span><span>Diferença: ${x.difference==null?'—':money(x.difference)}</span><span>Fechado por: ${escapeHtml(x.closedBy||'—')}</span></div></div>`).join('')||'<div class="card muted">Nenhum fechamento registrado ainda.</div>');return}
 let status=s?.status==='open'?`<span class="cash-status-open">● Caixa aberto</span>`:s?.status==='closed'?`<span class="cash-status-closed">Fechado</span>`:`<span class="cash-status-closed">Não aberto</span>`;let actions='';if(!s)actions=`<button class="btn btn-primary" onclick="openCashSessionModal()">Abrir caixa</button>`;else if(s.status==='open')actions=`<button class="btn btn-soft" onclick="openCashAdjustment('Suprimento')">+ Suprimento</button><button class="btn btn-ghost" onclick="openCashAdjustment('Sangria')">− Sangria</button><button class="btn btn-primary" onclick="openCloseCash()">Fechar caixa</button>`;else actions=`<button class="btn btn-soft" onclick="copyCashClosure('${s.id}')">Copiar WhatsApp</button><button class="btn btn-ghost" onclick="openReopenCash('${s.id}')">Reabrir caixa</button>`;
 adminPage.innerHTML=head+`<div class="cash-status-card"><div class="main"><h3>Caixa do dia ${formatDateBR(cashDate)} · ${escapeHtml(cashUnitName(uid))}</h3><div class="muted">${s?`Aberto por ${escapeHtml(s.openedBy||'—')} ${s.openedAt?'às '+formatTimeLocal(s.openedAt):''}`:'Abra o caixa para registrar saldo inicial, sangrias, suprimentos e fechamento.'}</div></div>${status}</div><div class="cash-kpis"><div class="cash-kpi emphasis"><span>Total recebido</span><b>${money(t.received)}</b></div><div class="cash-kpi"><span>Dinheiro recebido</span><b>${money(t.cash)}</b></div><div class="cash-kpi"><span>Pix</span><b>${money(t.pix)}</b></div><div class="cash-kpi"><span>Cartões</span><b>${money(t.cards)}</b></div><div class="cash-kpi"><span>Dinheiro físico esperado</span><b>${s?money(t.physicalExpected):'—'}</b></div></div>${t.sangrias?`<div class="inline-note" style="margin-bottom:12px"><b>Sangrias do dia: ${money(t.sangrias)}</b> · Despesas ${money(t.expenses)} · Vales/adiantamentos ${money(t.advances)} · Transferências ${money(t.transfers)}. Cada natureza segue separada no Financeiro/DRE.</div>`:''}<div class="cash-actions">${actions}<button class="btn btn-ghost" onclick="setCashTab('movements')">Ver todas as movimentações</button></div>${cashMovementTable(t.ms.slice(0,12))}`
}
function openCashSessionModal(){let uid=cashUnitId();modal('Abrir caixa',`<div class="inline-note" style="margin-bottom:12px"><b>${escapeHtml(cashUnitName(uid))}</b> · ${formatDateBR(cashDate)}<br>O saldo de abertura representa apenas o dinheiro físico existente no caixa no início do turno.</div><div class="field"><label>Saldo inicial em dinheiro</label><input id="cashOpeningAmount" type="number" min="0" step="0.01" value="0"></div>`,`<button class="btn btn-ghost" onclick="closeModal()">Cancelar</button><button class="btn btn-primary" onclick="saveOpenCashSession()">Abrir caixa</button>`)}
function saveOpenCashSession(){let uid=cashUnitId();if(cashSessionFor(uid,cashDate)){toast('Já existe um caixa para esta unidade e data');return}let opening=Math.max(0,Number(document.getElementById('cashOpeningAmount')?.value||0)),now=new Date();db.cashSessions.push({id:'cs'+Date.now(),unitId:uid,date:cashDate,status:'open',openingAmount:opening,openedAt:now.toISOString(),openedBy:currentUserName(),closedAt:null,closedBy:null,countedAmount:null,systemExpected:null,difference:null});db.cashAudits.push({id:'ca'+Date.now(),unitId:uid,date:cashDate,action:'Abertura',user:currentUserName(),at:now.toISOString(),note:`Saldo inicial ${money(opening)}`});save();closeModal();renderCash();toast('Caixa aberto ✓')}
function openCashAdjustment(type){let s=cashSessionFor();if(!s||s.status!=='open'){toast('Abra o caixa antes de registrar esta movimentação');return}if(type==='Suprimento'){modal('Suprimento',`<div class="form-grid"><div class="field"><label>Valor</label><input id="cashAdjAmount" type="number" min="0.01" step="0.01" placeholder="0,00"></div><div class="field full"><label>Motivo</label><input id="cashAdjReason" placeholder="Ex.: reforço de troco"></div></div><div class="inline-note">O suprimento aumenta o dinheiro físico esperado no fechamento e não é receita.</div>`,`<button class="btn btn-ghost" onclick="closeModal()">Cancelar</button><button class="btn btn-primary" onclick="saveCashAdjustment('Suprimento')">Salvar</button>`);return}
 modal('Sangria',`<div class="inline-note" style="margin-bottom:12px"><b>Sangria é a saída física do dinheiro.</b> Escolha a natureza para o Financeiro e o DRE tratarem corretamente.</div><div class="field"><label>Natureza da sangria</label><select id="cashAdjNature" onchange="cashAdjustmentTypeChanged()"><option value="expense">Despesa operacional</option><option value="employee_advance">Vale / adiantamento a funcionário</option><option value="transfer">Transferência / retirada de numerário</option></select></div><div id="cashAdjDynamic" style="margin-top:12px"></div>`,`<button class="btn btn-ghost" onclick="closeModal()">Cancelar</button><button class="btn btn-primary" onclick="saveCashAdjustment('Sangria')">Salvar sangria</button>`);cashAdjustmentTypeChanged()}
function cashAdjustmentTypeChanged(){let host=document.getElementById('cashAdjDynamic'),nature=document.getElementById('cashAdjNature')?.value||'expense';if(!host)return;let common=`<div class="form-grid"><div class="field"><label>Valor</label><input id="cashAdjAmount" type="number" min="0.01" step="0.01" placeholder="0,00"></div>`;if(nature==='expense'){host.innerHTML=common+`<div class="field"><label>Categoria financeira / DRE</label><select id="cashAdjCategory"><option>Copa e alimentação</option><option>Material de limpeza</option><option>Material de escritório</option><option>Manutenção emergencial</option><option>Transporte</option><option>Pequenas compras</option><option>Outros</option></select></div><div class="field full"><label>Descrição / motivo</label><input id="cashAdjReason" placeholder="Ex.: café e açúcar do supermercado"></div><div class="field full"><label>Fornecedor / comprovante</label><input id="cashAdjSupplier" placeholder="Opcional · ex.: Supermercado X / cupom guardado"></div></div><div class="inline-note"><b>A categoria é definida aqui, no momento da sangria.</b> Ao salvar, o lançamento já vai classificado para Caixa + Financeiro + DRE. Se houver erro, a reclassificação poderá ser feita depois no Financeiro por usuário autorizado.</div>`;return}if(nature==='employee_advance'){host.innerHTML=common+`<div class="field"><label>Funcionário / profissional</label><select id="cashAdjEmployee"><option value="">Selecione</option>${db.pros.filter(p=>p.active).map(p=>`<option value="${p.id}">${escapeHtml(p.name)}</option>`).join('')}</select></div><div class="field full"><label>Observação</label><input id="cashAdjReason" placeholder="Ex.: vale solicitado no dia"></div></div><label class="check"><input id="cashAdjDeductCommission" type="checkbox" checked> Abater automaticamente no próximo acerto de comissão</label><div class="inline-note"><b>Não é despesa no DRE.</b> A saída fica registrada como adiantamento ao colaborador e como dedução pendente no acerto da comissão.</div>`;return}host.innerHTML=common+`<div class="field"><label>Destino</label><select id="cashAdjTransferDest"><option>Cofre</option><option>Depósito bancário</option><option>Retirada administrativa</option><option>Outro</option></select></div><div class="field full"><label>Motivo</label><input id="cashAdjReason" placeholder="Ex.: retirada do excesso de numerário do caixa"></div></div><div class="inline-note"><b>Não é despesa no DRE.</b> Apenas reduz o dinheiro físico e registra a transferência no Financeiro.</div>`}
function saveCashAdjustment(type){let amount=typeof roundMoney==='function'?roundMoney(Math.max(0,Number(document.getElementById('cashAdjAmount')?.value||0))):Math.round(Math.max(0,Number(document.getElementById('cashAdjAmount')?.value||0))*100)/100;if(!(amount>0)){toast('Informe um valor válido');return}let reason=document.getElementById('cashAdjReason')?.value.trim()||type,uid=cashUnitId(),acc=cashPhysicalAccount(uid),now=new Date(),s=cashSessionFor(uid,cashDate);if(type==='Suprimento'){db.demoCashMovements.push({id:'cm'+Date.now(),unitId:uid,amount,paymentMethod:'Dinheiro',account:acc?.name||'Caixa físico',type:'Suprimento',cashNature:'supply',date:cashDate,createdAt:now.toISOString(),user:currentUserName(),note:reason,cashSessionId:s?.id||null,processorFee:0});db.cashAudits.push({id:'ca'+Date.now(),unitId:uid,date:cashDate,action:'Suprimento',user:currentUserName(),at:now.toISOString(),note:reason,amount});save();closeModal();renderCash();toast('Suprimento registrado ✓');return}
 let nature=document.getElementById('cashAdjNature')?.value||'expense',movement={id:'cm'+Date.now(),unitId:uid,amount:-amount,paymentMethod:'Dinheiro',account:acc?.name||'Caixa físico',type:'Sangria',cashNature:nature,date:cashDate,createdAt:now.toISOString(),user:currentUserName(),note:reason,cashSessionId:s?.id||null,processorFee:0};
 if(nature==='expense'){let category=document.getElementById('cashAdjCategory')?.value||'Outros',supplier=document.getElementById('cashAdjSupplier')?.value.trim()||'';movement.type='Sangria · Despesa';movement.category=category;movement.supplier=supplier;db.demoFinancialEntries.push({id:'fe'+Date.now(),unitId:uid,amount:-amount,nature:'Despesa operacional',category,account:acc?.name||'Caixa físico',date:cashDate,origin:reason,dreImpact:true,supplier});}
 else if(nature==='employee_advance'){let employeeId=document.getElementById('cashAdjEmployee')?.value||'';if(!employeeId){toast('Selecione o funcionário/profissional');return}let deduct=!!document.getElementById('cashAdjDeductCommission')?.checked;movement.type='Vale a funcionário';movement.employeeId=employeeId;movement.deductCommission=deduct;let pro=db.pros.find(p=>p.id===employeeId);db.demoFinancialEntries.push({id:'fe'+Date.now(),unitId:uid,amount:-amount,nature:'Adiantamento a colaborador',professionalId:employeeId,professionalName:pro?.name||'',account:acc?.name||'Caixa físico',date:cashDate,origin:reason,dreImpact:false});if(deduct)db.professionalCommissionAdjustments.push({id:'adj'+Date.now(),professionalId:employeeId,unitId:uid,date:cashDate,type:'Vale / adiantamento',amount:-amount,status:'Pendente de acerto',note:reason,createdBy:currentUserName()});}
 else{let dest=document.getElementById('cashAdjTransferDest')?.value||'Outro';movement.type='Sangria · Transferência';movement.destination=dest;db.demoFinancialEntries.push({id:'fe'+Date.now(),unitId:uid,amount:-amount,nature:'Transferência de caixa',account:acc?.name||'Caixa físico',destination:dest,date:cashDate,origin:reason,dreImpact:false});}
 db.demoCashMovements.push(movement);db.cashAudits.push({id:'ca'+Date.now()+Math.random(),unitId:uid,date:cashDate,action:movement.type,user:currentUserName(),at:now.toISOString(),note:reason,amount,nature});save();closeModal();renderCash();toast(nature==='employee_advance'?'Vale registrado e vinculado ao acerto ✓':'Sangria registrada ✓')}
function openCloseCash(){let t=cashTotals(),s=t.session;if(!s||s.status!=='open')return;modal(`Fechar caixa do dia ${formatDateBR(s.date)}`,`<div class="inline-note" style="margin-bottom:12px"><b>Data de referência do caixa: ${formatDateBR(s.date)}</b><br>Mesmo que o fechamento seja concluído no dia seguinte ou após uma reabertura, o resumo continuará vinculado a esta data.</div><div class="cash-close-grid"><div class="cash-close-box"><b>Resumo do dia</b><div class="row"><span>Saldo de abertura</span><b>${money(t.opening)}</b></div><div class="row"><span>Dinheiro recebido</span><b>${money(t.cash)}</b></div><div class="row"><span>Pix</span><b>${money(t.pix)}</b></div><div class="row"><span>Cartões</span><b>${money(t.cards)}</b></div><div class="row"><span>Gorjetas recebidas</span><b>${money(t.tips)}</b></div><div class="row"><span>Sangrias</span><b>− ${money(t.sangrias)}</b></div><div class="row total"><span>Total recebido</span><b>${money(t.received)}</b></div></div><div class="cash-close-box"><b>Conferência do dinheiro físico</b><div class="row"><span>Esperado pelo sistema</span><b>${money(t.physicalExpected)}</b></div><div class="field" style="margin-top:10px"><label>Valor contado no caixa</label><input id="cashCounted" type="number" min="0" step="0.01" value="${Math.max(0,t.physicalExpected).toFixed(2)}" oninput="updateCashCloseDiff()"></div><div id="cashCloseDiff" class="cash-diff ok">Diferença: ${money(0)}</div></div></div><div class="inline-note" style="margin-top:12px">Sangrias: despesas ${money(t.expenses)} · vales/adiantamentos ${money(t.advances)} · transferências ${money(t.transfers)}.</div><div class="field" style="margin-top:12px"><label>Observação do fechamento</label><textarea id="cashCloseNote" rows="3" placeholder="Opcional"></textarea></div>`,`<button class="btn btn-ghost" onclick="copyCurrentCashPreview()">Copiar prévia</button><button class="btn btn-ghost" onclick="closeModal()">Cancelar</button><button class="btn btn-primary" onclick="saveCloseCash()">Confirmar fechamento</button>`)}
function updateCashCloseDiff(){let t=cashTotals(),counted=Number(document.getElementById('cashCounted')?.value||0),diff=counted-t.physicalExpected,el=document.getElementById('cashCloseDiff');if(!el)return;el.className='cash-diff'+(Math.abs(diff)<.005?' ok':'');el.innerHTML=`Diferença: <b>${money(diff)}</b>${Math.abs(diff)>=.005?' · ficará registrada para conferência':''}`}
function saveCloseCash(){let t=cashTotals(),s=t.session;if(!s||s.status!=='open')return;let counted=Math.max(0,Number(document.getElementById('cashCounted')?.value||0)),now=new Date();s.status='closed';s.systemExpected=t.physicalExpected;s.countedAmount=counted;s.difference=counted-t.physicalExpected;s.closedAt=now.toISOString();s.closedBy=currentUserName();s.closeNote=document.getElementById('cashCloseNote')?.value.trim()||'';s.snapshot={received:t.received,cash:t.cash,pix:t.pix,cards:t.cards,fees:t.fees,sangrias:t.sangrias,expenses:t.expenses,advances:t.advances,transfers:t.transfers,tips:t.tips};db.cashAudits.push({id:'ca'+Date.now(),unitId:s.unitId,date:s.date,action:'Fechamento',user:currentUserName(),at:now.toISOString(),note:s.closeNote,difference:s.difference});save();closeModal();renderCash();toast(Math.abs(s.difference)<.005?'Caixa fechado sem diferença ✓ · resumo disponível para WhatsApp':`Caixa fechado · diferença ${money(s.difference)} · resumo disponível para WhatsApp`)}
async function copyTextSafe(text){try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(text);else throw new Error('clipboard')}catch(e){let ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove()}}
function cashClosureTextFromValues(unitName,date,user,closedAt,t,counted,diff,note=''){let lines=[`Fechamento do caixa do dia ${formatDateBR(date)}`,unitName,'',`Dinheiro: ${money(t.cash||0)}`,`Pix: ${money(t.pix||0)}`,`Cartões: ${money(t.cards||0)}`,`Total recebido: ${money(t.received||0)}`,`Gorjetas recebidas: ${money(t.tips||0)}`,'',`Sangrias: ${money(t.sangrias||0)}`,`• Despesas: ${money(t.expenses||0)}`,`• Vales/adiantamentos: ${money(t.advances||0)}`,`• Transferências: ${money(t.transfers||0)}`,'',`Dinheiro esperado: ${money(t.physicalExpected||0)}`,`Dinheiro contado: ${money(counted||0)}`,`Diferença: ${money(diff||0)}`,'',`Caixa fechado por: ${user||'—'}`];if(closedAt)lines.push(`Horário do fechamento: ${String(closedAt).slice(11,16)}`);if(String(note||'').trim())lines.push('',`Observação: ${String(note).trim()}`);return lines.join('\n')}
async function copyCurrentCashPreview(){let t=cashTotals(),counted=Math.max(0,Number(document.getElementById('cashCounted')?.value||0)),diff=counted-t.physicalExpected,note=document.getElementById('cashCloseNote')?.value.trim()||'',text=cashClosureTextFromValues(cashUnitName(),cashDate,currentUserName(),new Date().toISOString(),t,counted,diff,note);await copyTextSafe(text);toast('Resumo copiado para colar no WhatsApp ✓')}
async function copyCashClosure(id){let s=(db.cashSessions||[]).find(x=>x.id===id);if(!s)return;let snap=s.snapshot||{},vals={...snap,physicalExpected:Number(s.systemExpected||0)};let text=cashClosureTextFromValues(cashUnitName(s.unitId),s.date,s.closedBy,s.closedAt,vals,Number(s.countedAmount||0),Number(s.difference||0),s.closeNote||'');await copyTextSafe(text);toast('Fechamento copiado para o WhatsApp ✓')}
function openReopenCash(id){let s=db.cashSessions.find(x=>x.id===id);if(!s)return;modal('Reabrir caixa',`<div class="inline-note"><b>Ação auditada.</b> O fechamento anterior continuará registrado no histórico de auditoria.</div><div class="field" style="margin-top:12px"><label>Motivo da reabertura</label><textarea id="cashReopenReason" rows="3" placeholder="Informe o motivo"></textarea></div>`,`<button class="btn btn-ghost" onclick="closeModal()">Cancelar</button><button class="btn btn-primary" onclick="saveReopenCash('${id}')">Reabrir</button>`)}
function saveReopenCash(id){let s=db.cashSessions.find(x=>x.id===id),reason=document.getElementById('cashReopenReason')?.value.trim()||'';if(!s)return;if(!reason){toast('Informe o motivo da reabertura');return}let now=new Date();db.cashAudits.push({id:'ca'+Date.now(),unitId:s.unitId,date:s.date,action:'Reabertura',user:currentUserName(),at:now.toISOString(),note:reason,previousDifference:s.difference});s.status='open';s.reopenedAt=now.toISOString();s.reopenedBy=currentUserName();s.reopenReason=reason;save();closeModal();cashDate=s.date;cashTab='current';renderCash();toast('Caixa reaberto ✓')}

function renderPlaceholder(){subbar.textContent='Módulo previsto no escopo V1';adminPage.innerHTML=`<div class="card" style="max-width:760px"><span class="pill">Próxima etapa</span><h1 style="margin-bottom:8px">${({cash:'Caixa',stock:'Estoque',finance:'Financeiro',reports:'Relatórios'})[page]}</h1><p class="muted">O banco e as regras deste módulo já estão especificados. Nesta prévia visual estamos ativando primeiro Site, Agenda, Clientes, Profissionais e Serviços.</p></div>`}
function modal(title,body,footer=''){modalHost.innerHTML=`<div class="overlay" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><h2>${title}</h2><button class="x" onclick="closeModal()">×</button></div><div class="modal-body">${body}</div><div class="modal-foot">${footer}</div></div></div>`}
function closeModal(){modalHost.innerHTML=''}
function switchServiceTab(tab){
 document.querySelectorAll('.service-tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));
 document.querySelectorAll('.form-tabs button').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));
}
function setReturnFields(){let on=document.getElementById('sfReturn')?.checked;let box=document.getElementById('sfReturnDaysWrap');if(box)box.style.opacity=on?'1':'.45';if(document.getElementById('sfReturnDays'))document.getElementById('sfReturnDays').disabled=!on}
function serviceCategoryClientDefaults(catId){let cat=String(db.categories.find(c=>c.id===catId)?.name||'').toLowerCase(),name=String(document.getElementById('sfName')?.value||'').toLowerCase(),area=document.getElementById('sfClientArea'),lead=document.getElementById('sfLeadSameArea');if(!area||!lead)return;if(cat.includes('along')){area.value='hands';lead.checked=true;return}if(cat.includes('cabelo')){area.value='hair';lead.checked=false;return}if(cat.includes('cíli')||cat.includes('cili')||cat.includes('sobr')){area.value='face';lead.checked=false;return}if(name.includes('pedicure')||name.includes('pé'))area.value='feet';else if(cat.includes('manicure')||name.includes('manicure'))area.value='hands';lead.checked=false}
function resizeImage(file,maxW=1100,quality=.78){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{let scale=Math.min(1,maxW/img.width);let c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',quality))};img.onerror=reject;img.src=reader.result};reader.onerror=reject;reader.readAsDataURL(file)})}
async function serviceCoverChanged(input){if(!input.files?.[0])return;window.serviceDraftCover=await resizeImage(input.files[0]);document.getElementById('sfCoverPreview').src=window.serviceDraftCover;document.getElementById('sfCoverPreview').classList.remove('hidden')}
async function serviceGalleryChanged(input){let files=[...(input.files||[])].slice(0,5);window.serviceDraftGallery=[];for(const f of files){try{window.serviceDraftGallery.push(await resizeImage(f,900,.72))}catch{}}renderServiceGalleryPreview()}
function renderServiceGalleryPreview(){let host=document.getElementById('sfGalleryPreview');if(!host)return;host.innerHTML=(window.serviceDraftGallery||[]).map((src,i)=>`<div style="position:relative"><img class="upload-thumb" src="${src}"><button type="button" class="x" style="position:absolute;right:-5px;top:-5px;width:26px;height:26px;font-size:14px" onclick="serviceGalleryRemove(${i})">×</button></div>`).join('')}
function serviceGalleryRemove(i){window.serviceDraftGallery.splice(i,1);renderServiceGalleryPreview()}
function openServiceForm(id){
 let base=id?db.services.find(x=>x.id===id):null;
 let s=normalizeService(Object.assign({name:'',publicName:'',category:'c1',clientArea:'hands',mustFinishBeforeSameArea:false,price:'',duration:45,description:'',publicDescription:'',generatesReturn:false,returnDays:30,show:true,online:true,active:true,showPrice:true,priceMode:'fixed',websiteOrder:0,coverImage:'',gallery:[],proRules:{}},base||{}));
 window.serviceDraftCover=s.coverImage||'';window.serviceDraftGallery=[...(s.gallery||[])];
 const rows=db.pros.filter(p=>p.active).map(p=>{let r=(s.proRules||{})[p.id]||{};let enabled=r.enabled??(p.services||[]).includes(id);return `<tr class="service-pro-row" data-pro="${p.id}"><td><label class="check" style="margin:0"><input class="spr-enabled" type="checkbox" ${enabled?'checked':''}> <b>${escapeHtml(p.name)}</b></label><div class="muted" style="font-size:11px;margin-left:23px">${escapeHtml(p.specialty||'')}</div></td><td><input class="spr-duration" type="number" min="1" placeholder="${s.duration}" value="${r.duration??''}"></td><td><input class="spr-commission" type="number" min="0" max="100" step="0.01" placeholder="%" value="${r.commission??''}"></td><td><input class="spr-price" type="number" min="0" step="0.01" placeholder="Padrão" value="${r.price??''}"></td><td><input class="spr-online" type="checkbox" ${r.online!==false?'checked':''}></td></tr>`}).join('');
 modal(id?'Editar serviço':'Novo serviço',`<div class="form-tabs"><button type="button" class="active" data-tab="geral" onclick="switchServiceTab('geral')">Geral</button><button type="button" data-tab="profissionais" onclick="switchServiceTab('profissionais')">Profissionais</button><button type="button" data-tab="site" onclick="switchServiceTab('site')">Site</button></div>
 <div class="service-tab active" data-tab="geral"><div class="form-grid"><div class="field full"><label>Nome do serviço *</label><input id="sfName" value="${escapeAttr(s.name)}" placeholder="Ex.: Manutenção de gel" onblur="serviceCategoryClientDefaults(sfCat.value)"></div><div class="field"><label>Categoria *</label><select id="sfCat" onchange="serviceCategoryClientDefaults(this.value)">${db.categories.map(c=>`<option value="${c.id}" ${c.id===s.category?'selected':''}>${escapeHtml(c.name)}</option>`).join('')}</select></div><div class="field"><label>Preço padrão *</label><input id="sfPrice" type="number" min="0" step="0.01" value="${s.price}"></div><div class="field"><label>Duração padrão *</label><input id="sfDur" type="number" min="1" value="${s.duration}"></div><div class="field"><label>Status</label><select id="sfActive"><option value="1" ${s.active?'selected':''}>Ativo</option><option value="0" ${!s.active?'selected':''}>Inativo</option></select></div><div class="field full"><label>Descrição curta</label><textarea id="sfDesc" rows="3" maxlength="280" placeholder="Uma descrição objetiva do serviço para a equipe.">${escapeHtml(s.description||'')}</textarea><div class="help">Pode ser reaproveitada no site se você não escrever uma descrição pública diferente.</div></div></div><div class="section-box"><h3>Regras de simultaneidade da cliente</h3><div class="form-grid"><div class="field"><label>Área ocupada durante o serviço</label><select id="sfClientArea"><option value="none" ${s.clientArea==='none'?'selected':''}>Sem restrição / outra área</option><option value="hands" ${s.clientArea==='hands'?'selected':''}>Mãos</option><option value="feet" ${s.clientArea==='feet'?'selected':''}>Pés</option><option value="hair" ${s.clientArea==='hair'?'selected':''}>Cabelo</option><option value="face" ${s.clientArea==='face'?'selected':''}>Rosto</option></select></div><div class="field full"><label class="check" style="margin-top:8px"><input id="sfLeadSameArea" type="checkbox" ${s.mustFinishBeforeSameArea?'checked':''}> Este serviço deve terminar antes de outros serviços da mesma área</label><div class="help">Ex.: Manutenção/alongamento usa <b>Mãos</b> e pode ser marcada junto com Pedicure (<b>Pés</b>), mas a Manicure (<b>Mãos</b>) só será oferecida depois que a manutenção terminar.</div></div></div></div><div class="section-box"><h3>Retorno</h3><div class="switch-row"><div><b>Este serviço gera retorno?</b><div class="muted">Ao concluir, o sistema cria a previsão de retorno da cliente.</div></div><input id="sfReturn" type="checkbox" ${s.generatesReturn?'checked':''} onchange="setReturnFields()"></div><div id="sfReturnDaysWrap" class="field" style="margin-top:12px;max-width:260px"><label>Retorno sugerido em</label><div style="display:flex;align-items:center;gap:8px"><input id="sfReturnDays" type="number" min="1" value="${s.returnDays||30}"><span class="muted">dias</span></div></div></div></div>
 <div class="service-tab" data-tab="profissionais"><div class="tab-note">Defina quem executa o serviço. Campos vazios de duração e preço usam o padrão da aba Geral.</div><div class="pro-service-scroll"><table class="pro-service-table"><thead><tr><th>Profissional</th><th>Duração (min)</th><th>Comissão %</th><th>Preço específico</th><th>Online</th></tr></thead><tbody>${rows||'<tr><td colspan="5" class="muted">Nenhuma profissional ativa cadastrada.</td></tr>'}</tbody></table></div><div class="help" style="margin-top:10px">A Agenda só oferece este serviço para profissionais marcadas como executantes. Comissão e duração ficam vinculadas à profissional.</div></div>
 <div class="service-tab" data-tab="site"><div class="form-grid"><div class="field"><label>Nome público</label><input id="sfPublicName" value="${escapeAttr(s.publicName||'')}" placeholder="Se vazio, usa o nome do serviço"></div><div class="field"><label>Ordem de exibição</label><input id="sfOrder" type="number" min="0" value="${s.websiteOrder||0}"></div><div class="field full"><label>Descrição para o site</label><textarea id="sfPublicDesc" rows="4" maxlength="500" placeholder="Explique de forma simples o que a cliente vai encontrar.">${escapeHtml(s.publicDescription||'')}</textarea></div></div><div class="section-box"><h3>Publicação</h3><label class="check"><input id="sfShow" type="checkbox" ${s.show?'checked':''}> Exibir este serviço no site</label><label class="check"><input id="sfOnline" type="checkbox" ${s.online?'checked':''}> Permitir agendamento online</label><label class="check"><input id="sfShowPrice" type="checkbox" ${s.showPrice!==false?'checked':''}> Mostrar preço para a cliente</label><div class="field" style="max-width:270px;margin-top:12px"><label>Como exibir o preço</label><select id="sfPriceMode"><option value="fixed" ${s.priceMode!=='starting'?'selected':''}>Preço</option><option value="starting" ${s.priceMode==='starting'?'selected':''}>A partir de</option></select></div></div><div class="section-box"><h3>Fotos do serviço</h3><div class="upload-box"><div class="field"><label>Foto principal</label><input type="file" accept="image/*" onchange="serviceCoverChanged(this)"><div class="help">Opcional. Será usada como capa do serviço no site.</div><img id="sfCoverPreview" class="cover-preview ${s.coverImage?'':'hidden'}" src="${s.coverImage||''}"></div><div class="field" style="margin-top:16px"><label>Galeria (até 5 fotos)</label><input type="file" accept="image/*" multiple onchange="serviceGalleryChanged(this)"><div class="help">Fotos adicionais para a página de detalhes do serviço.</div><div id="sfGalleryPreview" class="upload-preview"></div></div></div></div></div>`,`<button class="btn btn-ghost" onclick="closeModal()">Cancelar</button>${id?`<button class="btn btn-ghost" onclick="duplicateService('${id}')">Duplicar</button>`:''}<button class="btn btn-primary" onclick="saveService('${id||''}')">${id?'Salvar alterações':'Salvar serviço'}</button>`);
 setTimeout(()=>{document.querySelector('#modalHost .modal')?.classList.add('modal-wide');setReturnFields();renderServiceGalleryPreview()},0)
}
function saveService(id){
 if(!sfName.value.trim()){toast('Informe o nome do serviço');switchServiceTab('geral');sfName.focus();return}
 if(!sfPrice.value||Number(sfPrice.value)<0){toast('Informe um preço válido');switchServiceTab('geral');return}
 if(!sfDur.value||Number(sfDur.value)<=0){toast('Informe a duração do serviço');switchServiceTab('geral');return}
 let obj=id?db.services.find(x=>x.id===id):{id:'s'+Date.now()};
 let rules={};document.querySelectorAll('.service-pro-row').forEach(row=>{let pid=row.dataset.pro;let enabled=row.querySelector('.spr-enabled').checked;let duration=Number(row.querySelector('.spr-duration').value)||null;let commission=row.querySelector('.spr-commission').value===''?null:Number(row.querySelector('.spr-commission').value);let price=row.querySelector('.spr-price').value===''?null:Number(row.querySelector('.spr-price').value);let online=row.querySelector('.spr-online').checked;rules[pid]={enabled,duration,commission,price,online}});
 Object.assign(obj,{name:sfName.value.trim(),publicName:sfPublicName.value.trim(),category:sfCat.value,clientArea:sfClientArea.value||'none',mustFinishBeforeSameArea:!!sfLeadSameArea.checked,price:Number(sfPrice.value),duration:Number(sfDur.value),description:sfDesc.value.trim(),publicDescription:sfPublicDesc.value.trim(),generatesReturn:sfReturn.checked,returnDays:sfReturn.checked?Number(sfReturnDays.value)||null:null,active:sfActive.value==='1',show:sfShow.checked,online:sfOnline.checked,showPrice:sfShowPrice.checked,priceMode:sfPriceMode.value,websiteOrder:Number(sfOrder.value)||0,coverImage:window.serviceDraftCover||'',gallery:[...(window.serviceDraftGallery||[])],proRules:rules});
 if(!id)db.services.push(obj);
 db.pros.forEach(p=>{p.services=p.services||[];let enabled=rules[p.id]?.enabled;if(enabled&&!p.services.includes(obj.id))p.services.push(obj.id);if(!enabled)p.services=p.services.filter(x=>x!==obj.id)});
 save();closeModal();renderServices();toast(id?'Serviço atualizado':'Serviço cadastrado')
}
function duplicateService(id){let s=db.services.find(x=>x.id===id);if(!s)return;let copy=structuredClone(s);copy.id='s'+Date.now();copy.name=s.name+' - cópia';copy.active=false;copy.show=false;copy.online=false;db.services.push(copy);save();closeModal();renderServices();toast('Serviço duplicado como inativo')}

function toggleService(id){let s=db.services.find(x=>x.id===id);s.active=!s.active;save();renderServices();toast(s.active?'Serviço ativado':'Serviço desativado')}
function switchProTab(tab){
 document.querySelectorAll('.pro-tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));
 document.querySelectorAll('.pro-form-tabs button').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));
 if(tab==='comissoes')renderProCommissionSummary();
}
async function proPhotoChanged(input){if(!input.files?.[0])return;window.proDraftPhoto=await resizeImage(input.files[0],700,.8);let img=document.getElementById('pfPhotoPreview');let ph=document.getElementById('pfPhotoPlaceholder');if(img){img.src=window.proDraftPhoto;img.classList.remove('hidden')}if(ph)ph.classList.add('hidden')}
function pfCompanyToggle(){let on=document.getElementById('pfHasCompany')?.checked;document.querySelectorAll('.pj-field').forEach(x=>{x.style.opacity=on?'1':'.45';x.querySelectorAll('input').forEach(i=>i.disabled=!on)})}
function syncProUnitScheduleAvailability(){let selected=new Set([...document.querySelectorAll('.pfUnit:checked')].map(x=>x.value));document.querySelectorAll('.schedule-row').forEach(r=>{let enabled=selected.has(r.dataset.unit);r.style.opacity=enabled?'1':'.42';r.querySelectorAll('input').forEach(i=>{i.disabled=!enabled})})}
function renderProCommissionSummary(){let host=document.getElementById('pfCommissionSummary');if(!host)return;let rows=[...document.querySelectorAll('.pro-service-row')].filter(r=>r.querySelector('.pfr-enabled')?.checked);let commissions=rows.map(r=>Number(r.querySelector('.pfr-commission')?.value)).filter(x=>!Number.isNaN(x)&&x>=0);let avg=commissions.length?commissions.reduce((a,b)=>a+b,0)/commissions.length:0;host.innerHTML=`<div class=\"summary-kpis\"><div class=\"card\"><span class=\"muted\">Serviços habilitados</span><b>${rows.length}</b></div><div class=\"card\"><span class=\"muted\">Comissões configuradas</span><b>${commissions.length}</b></div><div class=\"card\"><span class=\"muted\">Média configurada</span><b>${avg?avg.toFixed(1)+'%':'—'}</b></div></div><div class=\"table-card\"><table class=\"table\"><thead><tr><th>Serviço</th><th>Comissão</th><th>Duração</th><th>Preço</th></tr></thead><tbody>${rows.map(r=>{let sid=r.dataset.service,srv=db.services.find(x=>x.id===sid),c=r.querySelector('.pfr-commission').value,d=r.querySelector('.pfr-duration').value,pr=r.querySelector('.pfr-price').value;return `<tr><td><b>${escapeHtml(srv?.name||'')}</b></td><td>${c!==''?escapeHtml(c)+'%':'Não definida'}</td><td>${d||srv?.duration||'—'} min</td><td>${pr!==''?money(pr):'Padrão'}</td></tr>`}).join('')||'<tr><td colspan=\"4\" class=\"muted\">Nenhum serviço habilitado.</td></tr>'}</tbody></table></div><div class=\"help\" style=\"margin-top:10px\">A edição das comissões é feita na aba Serviços. No sistema definitivo esta aba também exibirá comissões geradas, pagamentos diretos, ajustes e saldo a pagar.</div>`}
function openProForm(id){
 let existing=id?db.pros.find(x=>x.id===id):null;let draftId=id||('p'+Date.now());
 let p=normalizeProfessional(Object.assign({id:draftId,name:'',publicName:'',specialty:'',bio:'',units:[],show:true,online:true,active:true,services:[],schedule:{}},existing?structuredClone(existing):{}));
 window.proDraftId=draftId;window.proDraftPhoto=p.photo||'';
 const weekdays=['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'];
 const scheduleRows=db.units.map(u=>weekdays.map((day,idx)=>{let key=u.id+'-'+idx,r=(p.schedule||{})[key]||{};let selected=(p.units||[]).includes(u.id);return `<tr class=\"schedule-row\" data-unit=\"${u.id}\" data-day=\"${idx}\" style=\"opacity:${selected?'1':'.42'}\"><td><b>${escapeHtml(u.name)}</b></td><td>${day}</td><td><input class=\"pfs-work\" type=\"checkbox\" ${r.work?'checked':''} ${selected?'':'disabled'}></td><td><input class=\"pfs-start\" type=\"time\" value=\"${r.start||'09:00'}\" ${selected?'':'disabled'}></td><td><input class=\"pfs-end\" type=\"time\" value=\"${r.end||'18:00'}\" ${selected?'':'disabled'}></td></tr>`}).join('')).join('');
 const serviceRows=db.services.filter(s=>s.active).map(srv=>{let r=(srv.proRules||{})[draftId]||{},enabled=r.enabled??(p.services||[]).includes(srv.id);return `<tr class=\"pro-service-row\" data-service=\"${srv.id}\"><td><label class=\"check\" style=\"margin:0\"><input class=\"pfr-enabled\" type=\"checkbox\" ${enabled?'checked':''}> <b>${escapeHtml(srv.name)}</b></label><div class=\"muted\" style=\"font-size:11px;margin-left:23px\">${escapeHtml(db.categories.find(c=>c.id===srv.category)?.name||'')}</div></td><td><input class=\"pfr-duration\" type=\"number\" min=\"1\" placeholder=\"${srv.duration}\" value=\"${r.duration??''}\"></td><td><input class=\"pfr-commission\" type=\"number\" min=\"0\" max=\"100\" step=\"0.01\" placeholder=\"%\" value=\"${r.commission??''}\"></td><td><input class=\"pfr-price\" type=\"number\" min=\"0\" step=\"0.01\" placeholder=\"Padrão\" value=\"${r.price??''}\"></td><td><input class=\"pfr-online\" type=\"checkbox\" ${r.online!==false?'checked':''}></td></tr>`}).join('');
 modal(id?'Editar profissional':'Nova profissional',`<div class=\"form-tabs pro-form-tabs\"><button type=\"button\" class=\"active\" data-tab=\"perfil\" onclick=\"switchProTab('perfil')\">Perfil</button><button type=\"button\" data-tab=\"pessoais\" onclick=\"switchProTab('pessoais')\">Dados pessoais</button><button type=\"button\" data-tab=\"pj\" onclick=\"switchProTab('pj')\">PJ / MEI</button><button type=\"button\" data-tab=\"bancario\" onclick=\"switchProTab('bancario')\">Bancário / Pix</button><button type=\"button\" data-tab=\"horarios\" onclick=\"switchProTab('horarios')\">Horários</button><button type=\"button\" data-tab=\"servicos\" onclick=\"switchProTab('servicos')\">Serviços</button><button type=\"button\" data-tab=\"comissoes\" onclick=\"switchProTab('comissoes')\">Comissões</button></div>
 <div class=\"pro-tab active\" data-tab=\"perfil\"><div class=\"pro-photo-row\"><div>${p.photo?`<img id=\"pfPhotoPreview\" class=\"pro-photo\" src=\"${p.photo}\"><div id=\"pfPhotoPlaceholder\" class=\"pro-photo-placeholder hidden\">${initials(p.publicName||p.name||'P')}</div>`:`<img id=\"pfPhotoPreview\" class=\"pro-photo hidden\"><div id=\"pfPhotoPlaceholder\" class=\"pro-photo-placeholder\">${initials(p.publicName||p.name||'P')}</div>`}</div><div class=\"field\"><label>Foto da profissional</label><input type=\"file\" accept=\"image/*\" onchange=\"proPhotoChanged(this)\"><div class=\"help\">Opcional. Pode ser exibida no site se a profissional estiver publicada.</div></div></div><div class=\"form-grid\" style=\"margin-top:18px\"><div class=\"field\"><label>Nome completo *</label><input id=\"pfName\" value=\"${escapeAttr(p.name)}\"></div><div class=\"field\"><label>Nome público / apelido</label><input id=\"pfPublicName\" value=\"${escapeAttr(p.publicName||'')}\" placeholder=\"Como aparecerá para a cliente\"></div><div class=\"field\"><label>Especialidade</label><input id=\"pfSpec\" value=\"${escapeAttr(p.specialty||'')}\"></div><div class=\"field\"><label>Cor na Agenda</label><input id=\"pfAgendaColor\" type=\"color\" value=\"${escapeAttr(p.agendaColor||defaultAgendaColor(p))}\" style=\"height:42px;padding:4px\"></div><div class=\"field\"><label>Status</label><select id=\"pfActive\"><option value=\"1\" ${p.active?'selected':''}>Ativa</option><option value=\"0\" ${!p.active?'selected':''}>Inativa</option></select></div><div class=\"field full\"><label>Bio pública</label><textarea id=\"pfBio\" rows=\"3\" maxlength=\"400\" placeholder=\"Pequena apresentação para o site.\">${escapeHtml(p.bio||'')}</textarea></div><div class=\"field full\"><label>Unidades onde trabalha *</label>${db.units.filter(u=>u.active).map(u=>`<label class=\"check\"><input class=\"pfUnit\" type=\"checkbox\" value=\"${u.id}\" ${(p.units||[]).includes(u.id)?'checked':''} onchange=\"syncProUnitScheduleAvailability()\"> ${escapeHtml(u.name)}</label>`).join('')}</div></div><div class=\"section-box\"><h3>Exibição pública</h3><label class=\"check\"><input id=\"pfShow\" type=\"checkbox\" ${p.show?'checked':''}> Exibir no site</label><label class=\"check\"><input id=\"pfOnline\" type=\"checkbox\" ${p.online?'checked':''}> Permitir agendamento online</label></div></div>
 <div class=\"pro-tab\" data-tab=\"pessoais\"><div class=\"form-grid\"><div class=\"field\"><label>CPF</label><input id=\"pfCpf\" value=\"${escapeAttr(p.cpf||'')}\" placeholder=\"000.000.000-00\"></div><div class=\"field\"><label>Data de nascimento</label><input id=\"pfBirth\" type=\"date\" value=\"${escapeAttr(p.birthDate||'')}\"></div><div class=\"field\"><label>Telefone / celular</label><input id=\"pfPhone\" value=\"${escapeAttr(p.phone||'')}\"></div><div class=\"field\"><label>E-mail</label><input id=\"pfEmail\" type=\"email\" value=\"${escapeAttr(p.email||'')}\"></div><div class=\"field full\"><label>Observações internas</label><textarea id=\"pfNotes\" rows=\"4\">${escapeHtml(p.notes||'')}</textarea></div></div></div>
 <div class=\"pro-tab\" data-tab=\"pj\"><div class=\"section-box\" style=\"margin-top:0\"><div class=\"switch-row\"><div><b>Possui CNPJ / MEI?</b><div class=\"muted\">Ative para registrar os dados empresariais da profissional.</div></div><input id=\"pfHasCompany\" type=\"checkbox\" ${p.hasCompany?'checked':''} onchange=\"pfCompanyToggle()\"></div></div><div class=\"form-grid\" style=\"margin-top:14px\"><div class=\"field pj-field\"><label>CNPJ</label><input id=\"pfCnpj\" value=\"${escapeAttr(p.cnpj||'')}\"></div><div class=\"field pj-field\"><label>Razão social</label><input id=\"pfLegalName\" value=\"${escapeAttr(p.legalName||'')}\"></div><div class=\"field pj-field full\"><label>Nome fantasia</label><input id=\"pfTradeName\" value=\"${escapeAttr(p.tradeName||'')}\"></div><div class=\"field pj-field full\"><label>Final da vigência do contrato</label><input id=\"pfContractEnd\" type=\"date\" value=\"${escapeAttr(p.contractEndDate||'')}\"><div class=\"help\">Ao atingir esta data, o sistema gera uma notificação/tarefa para renovação do contrato.</div></div></div></div>
 <div class=\"pro-tab\" data-tab=\"bancario\"><div class=\"form-grid\"><div class=\"field\"><label>Banco</label><input id=\"pfBank\" value=\"${escapeAttr(p.bank||'')}\" placeholder=\"Ex.: Itaú\"></div><div class=\"field\"><label>Titular</label><input id=\"pfHolder\" value=\"${escapeAttr(p.accountHolder||'')}\"></div><div class=\"field\"><label>Agência</label><input id=\"pfAgency\" value=\"${escapeAttr(p.agency||'')}\"></div><div class=\"field\"><label>Conta</label><input id=\"pfAccount\" value=\"${escapeAttr(p.account||'')}\"></div><div class=\"field\"><label>Tipo de conta</label><select id=\"pfAccountType\"><option ${p.accountType==='Corrente'?'selected':''}>Corrente</option><option ${p.accountType==='Poupança'?'selected':''}>Poupança</option><option ${p.accountType==='Pagamento'?'selected':''}>Pagamento</option></select></div><div class=\"field\"><label>Tipo de chave Pix</label><select id=\"pfPixType\"><option ${p.pixType==='CPF'?'selected':''}>CPF</option><option ${p.pixType==='Celular'?'selected':''}>Celular</option><option ${p.pixType==='E-mail'?'selected':''}>E-mail</option><option ${p.pixType==='Aleatória'?'selected':''}>Aleatória</option></select></div><div class=\"field full\"><label>Chave Pix</label><input id=\"pfPixKey\" value=\"${escapeAttr(p.pixKey||'')}\" placeholder=\"Número, CPF, e-mail ou chave aleatória\"></div></div><div class=\"help\">Dados bancários são internos e não aparecem no site público.</div></div>
 <div class=\"pro-tab\" data-tab=\"horarios\"><div class=\"tab-note\">Defina a escala padrão por unidade. Alterações pontuais, folgas, atrasos e horários extras serão feitas como exceções, sem apagar esta escala.</div><div class=\"schedule-scroll\"><table class=\"schedule-table\"><thead><tr><th>Unidade</th><th>Dia</th><th>Trabalha</th><th>Entrada</th><th>Saída</th></tr></thead><tbody>${scheduleRows}</tbody></table></div></div>
 <div class=\"pro-tab\" data-tab=\"servicos\"><div class=\"tab-note\">Habilite os serviços que esta profissional executa. Os mesmos vínculos aparecem automaticamente no cadastro de cada serviço.</div><div class=\"pro-service-scroll\"><table class=\"pro-service-table\"><thead><tr><th>Serviço</th><th>Duração (min)</th><th>Comissão %</th><th>Preço específico</th><th>Online</th></tr></thead><tbody>${serviceRows||'<tr><td colspan=\"5\" class=\"muted\">Nenhum serviço ativo cadastrado.</td></tr>'}</tbody></table></div><div class=\"help\" style=\"margin-top:10px\">Campo vazio de duração ou preço usa o padrão do serviço. A Agenda respeitará exatamente estes vínculos.</div></div>
 <div class=\"pro-tab\" data-tab=\"comissoes\"><div id=\"pfCommissionSummary\"></div></div>`, `<button class=\"btn btn-ghost\" onclick=\"closeModal()\">Cancelar</button><button class=\"btn btn-primary\" onclick=\"savePro('${id||''}')\">${id?'Salvar alterações':'Salvar profissional'}</button>`);
 setTimeout(()=>{document.querySelector('#modalHost .modal')?.classList.add('modal-wide');pfCompanyToggle();syncProUnitScheduleAvailability()},0)
}
function savePro(id){
 if(!pfName.value.trim()){toast('Informe o nome completo da profissional');switchProTab('perfil');pfName.focus();return}
 let units=[...document.querySelectorAll('.pfUnit:checked')].map(x=>x.value).filter(uid=>(db.units||[]).some(u=>u.id===uid&&u.active!==false));if(!units.length){toast('Selecione pelo menos uma unidade válida');switchProTab('perfil');return}
 let pid=id||window.proDraftId;let p=id?db.pros.find(x=>x.id===id):{id:pid,services:[]};normalizeProfessional(p);
 let schedule={};document.querySelectorAll('.schedule-row').forEach(r=>{if(!units.includes(r.dataset.unit))return;let work=r.querySelector('.pfs-work').checked;let start=r.querySelector('.pfs-start').value,end=r.querySelector('.pfs-end').value;schedule[r.dataset.unit+'-'+r.dataset.day]={work,start,end}});
 let serviceIds=[];document.querySelectorAll('.pro-service-row').forEach(row=>{let sid=row.dataset.service,srv=db.services.find(x=>x.id===sid);if(!srv)return;srv.proRules=srv.proRules||{};let enabled=row.querySelector('.pfr-enabled').checked;let duration=row.querySelector('.pfr-duration').value===''?null:Number(row.querySelector('.pfr-duration').value);let commission=row.querySelector('.pfr-commission').value===''?null:Number(row.querySelector('.pfr-commission').value);let price=row.querySelector('.pfr-price').value===''?null:Number(row.querySelector('.pfr-price').value);let online=row.querySelector('.pfr-online').checked;srv.proRules[pid]={enabled,duration,commission,price,online};if(enabled)serviceIds.push(sid)});
 Object.assign(p,{name:pfName.value.trim(),publicName:pfPublicName.value.trim()||pfName.value.trim(),specialty:pfSpec.value.trim(),agendaColor:pfAgendaColor.value||defaultAgendaColor(p),bio:pfBio.value.trim(),units,show:pfShow.checked,online:pfOnline.checked,active:pfActive.value==='1',photo:window.proDraftPhoto||'',cpf:pfCpf.value.trim(),birthDate:pfBirth.value,phone:pfPhone.value.trim(),email:pfEmail.value.trim(),notes:pfNotes.value.trim(),hasCompany:pfHasCompany.checked,cnpj:pfHasCompany.checked?pfCnpj.value.trim():'',legalName:pfHasCompany.checked?pfLegalName.value.trim():'',tradeName:pfHasCompany.checked?pfTradeName.value.trim():'',contractEndDate:pfHasCompany.checked?pfContractEnd.value:'',bank:pfBank.value.trim(),agency:pfAgency.value.trim(),account:pfAccount.value.trim(),accountType:pfAccountType.value,accountHolder:pfHolder.value.trim(),pixType:pfPixType.value,pixKey:pfPixKey.value.trim(),schedule,services:serviceIds});
 if(!id)db.pros.push(p);save();closeModal();renderPros();buildAdminNav();toast(id?'Profissional atualizada':'Profissional cadastrada e integrada ao sistema')
}
function togglePro(id){let p=db.pros.find(x=>x.id===id);p.active=!p.active;save();renderPros();toast(p.active?'Profissional ativada':'Profissional desativada')}
function openSourceManager(){
 modal('Como conheceu o Império?',`<p class="muted">Gerencie as opções usadas no cadastro e nos relatórios de marketing. Itens desativados continuam preservados no histórico.</p><div class="form-grid"><div class="field full"><label>Nova opção</label><div style="display:flex;gap:8px"><input id="newSourceName" placeholder="Ex.: Inteligência Artificial, Blogueira X"><button class="btn btn-primary" onclick="addAcquisitionSource()">Adicionar</button></div></div></div><div id="sourceManagerList" class="source-list"></div>`,`<button class="btn btn-ghost" onclick="closeModal()">Fechar</button>`);
 renderSourceManagerList()
}
function renderSourceManagerList(){let el=document.getElementById('sourceManagerList');if(!el)return;el.innerHTML=db.acquisitionSources.map(x=>`<div class="source-row"><input value="${escapeAttr(x.name)}" onchange="renameAcquisitionSource('${x.id}',this.value)"><div class="spacer"></div><button class="btn ${x.active?'btn-soft':'btn-ghost'} btn-sm" onclick="toggleAcquisitionSource('${x.id}')">${x.active?'Ativa':'Inativa'}</button></div>`).join('')}
function addAcquisitionSource(){let name=newSourceName.value.trim();if(!name)return;if(db.acquisitionSources.some(x=>normName(x.name)===normName(name))){toast('Essa opção já existe');return}db.acquisitionSources.push({id:'as'+Date.now(),name,active:true});save();newSourceName.value='';renderSourceManagerList();toast('Nova opção adicionada')}
function renameAcquisitionSource(id,name){let x=db.acquisitionSources.find(a=>a.id===id);if(!x||!name.trim())return;x.name=name.trim();save()}
function toggleAcquisitionSource(id){let x=db.acquisitionSources.find(a=>a.id===id);if(!x)return;x.active=!x.active;save();renderSourceManagerList()}
function openClientForm(id=null){
 let c=id?db.clients.find(x=>x.id===id):null;if(c)normalizeClient(c);
 modal(id?'Editar cliente':'Nova cliente',`
 <div class="client-section"><h3>Dados pessoais</h3><div class="form-grid">
  <div class="field full"><label class="required">Nome completo</label><input id="cfName" value="${escapeAttr(c?.name||'')}"></div>
  <div class="field"><label>Data de nascimento</label><input id="cfBirth" type="date" value="${c?.birthDate||''}"></div>
  <div class="field"><label>CPF</label><input id="cfCpf" value="${escapeAttr(c?.cpf||'')}" placeholder="Somente para identificação e cadastro"></div>
  <div class="field"><label class="required">Celular / telefone</label><input id="cfPhone" value="${escapeAttr(c?.phone||'')}" oninput="clientPhoneHint('${id||''}')"></div>
  <div class="field"><label>E-mail</label><input id="cfEmail" type="email" value="${escapeAttr(c?.email||'')}"></div>
  <div class="field"><label>Profissão <span class="muted">(opcional)</span></label><input id="cfProfession" value="${escapeAttr(c?.profession||'')}"></div>
  <div class="field full"><div id="cfPhoneHint" class="inline-note hidden"></div></div>
 </div></div>
 <div class="client-section"><h3>Localização</h3><div class="form-grid">
  <div class="field"><label>CEP</label><input id="cfCep" value="${escapeAttr(c?.cep||'')}" placeholder="00000-000" onblur="fillClientNeighborhood()"></div>
  <div class="field"><label>Bairro</label><input id="cfNeighborhood" value="${escapeAttr(c?.neighborhood||'')}" placeholder="Preenchido pelo CEP quando disponível"></div>
  <div class="field"><label>Cidade</label><input id="cfCity" value="${escapeAttr(c?.city||'')}" placeholder="Preenchida pelo CEP quando disponível"></div>
 </div><div class="help">O sistema usa CEP, bairro e cidade. Rua, número e complemento não são necessários.</div></div>
 <div class="client-section"><h3>Relacionamento</h3><div class="form-grid">
  <div class="field"><label class="required">Como conheceu o Império?</label><select id="cfSource"><option value="">Selecione</option>${sourceOptions(c?.source||'')}</select></div>
  <div class="field"><label>Origem do cadastro</label><select id="cfOrigin" ${id?'disabled':''}>${originOptions(c?.origin||'Presencial')}</select><div class="help">Canal em que o cadastro chegou: presencial, WhatsApp, telefone etc.</div></div>
  <div class="field"><label>Cadastrado por</label><input value="${escapeAttr(c?.createdBy||currentUserName())}" readonly></div>
  <div class="field"><label>Unidade do cadastro</label><input value="${escapeAttr(db.units.find(u=>u.id===(c?.registrationUnit||(unitPicker?.value||'')))?.name||'—')}" readonly></div>
  <div class="field full"><label>Observações</label><textarea id="cfNotes" rows="3">${escapeHtml(c?.notes||'')}</textarea></div>
 </div></div>`,
 `<button class="btn btn-ghost" onclick="closeModal()">Cancelar</button><button class="btn btn-primary" onclick="saveClient('${id||''}')">${id?'Salvar alterações':'Salvar cliente'}</button>`);
 setTimeout(()=>clientPhoneHint(id||''),0)
}
function clientPhoneHint(id=''){let el=document.getElementById('cfPhoneHint');if(!el)return;let d=digits(cfPhone.value);if(d.length<8){el.classList.add('hidden');return}let matches=db.clients.filter(c=>c.id!==id&&digits(c.phone)===d);if(matches.length){el.textContent=`Este telefone já está ligado a ${matches.length} cadastro(s). Isso não bloqueia o cadastro, pois o contato pode ser compartilhado entre familiares.`;el.classList.remove('hidden')}else el.classList.add('hidden')}
function fillClientNeighborhood(){let loc=cepLookup(cfCep.value);if(loc){if(!cfNeighborhood.value.trim())cfNeighborhood.value=loc.neighborhood||'';if(document.getElementById('cfCity')&&!cfCity.value.trim())cfCity.value=loc.city||''}else if(digits(cfCep.value).length===8)toast('CEP não está na base demonstrativa. Preencha bairro e cidade manualmente.')}
function saveClient(id=''){
 if(!cfName.value.trim()||!cfPhone.value.trim()||!cfSource.value){toast('Preencha nome, celular e como conheceu o Império');return}
 let cpf=digits(cfCpf.value);if(cpf){let duplicate=db.clients.find(c=>c.id!==id&&digits(c.cpf)===cpf);if(duplicate){toast('Já existe uma cliente com este CPF. Revise antes de salvar.');return}}
 let selectedUnit=unitPicker?.value||'';if(!id&&!(db.units||[]).some(u=>u.id===selectedUnit&&u.active!==false)){toast('Selecione uma unidade válida no topo antes de cadastrar a cliente');return}let c=id?db.clients.find(x=>x.id===id):{id:'cl'+Date.now(),last:'—',next:'—',visits:0,origin:cfOrigin.value||'Presencial',createdBy:currentUserName(),registrationUnit:selectedUnit,createdAt:localDateISO()};normalizeClient(c);
 Object.assign(c,{name:cfName.value.trim(),birthDate:cfBirth.value,cpf,email:cfEmail.value.trim(),phone:cfPhone.value.trim(),cep:cfCep.value.trim(),neighborhood:cfNeighborhood.value.trim(),city:cfCity.value.trim(),profession:cfProfession.value.trim(),source:cfSource.value,notes:cfNotes.value.trim()});
 if(!id)db.clients.push(c);save();closeModal();renderClients();toast(id?'Cliente atualizada':'Cliente cadastrada')
}
function clientCreditBalance(clientId){return (db.clientCreditMovements||[]).filter(x=>x.clientId===clientId).reduce((a,x)=>a+Number(x.amount||0),0)}
function clientActivePackages(clientId){return (db.clientPackages||[]).filter(x=>x.clientId===clientId&&x.status==='Ativo')}
function clientAllAppointments(clientId){
 let c=db.clients.find(x=>x.id===clientId),bookingIds=new Set((db.bookings||[]).map(b=>b.id));
 let rows=(db.clientAppointments||[]).filter(x=>x.clientId===clientId&&!bookingIds.has(x.id)).map(x=>({...x,kind:'history'}));
 (db.bookings||[]).filter(b=>b.clientId===clientId||(c&&normName(b.client)===normName(c.name))).forEach(b=>{normalizeBooking(b);b.items.forEach((it,i)=>rows.push({id:`${b.id}:${i}`,bookingId:b.id,clientId,date:b.date,time:it.time,unitId:b.unit,service:it.service,professional:db.pros.find(p=>p.id===it.pro)?.name||'Sem preferência',status:b.status,value:Number(it.price||0),kind:'booking'}))});
 return rows.sort((a,b)=>(b.date+' '+(b.time||'')).localeCompare(a.date+' '+(a.time||'')));
}
function openClient(id,tab='resumo'){
 let c=db.clients.find(x=>x.id===id);if(!c)return;normalizeClient(c);window.clientProfileId=id;
 let credit=clientCreditBalance(id),packs=clientActivePackages(id);
 modal('',`<div class="client-profile-header"><div class="avatar">${initials(c.name)}</div><div class="client-profile-title"><h2>${escapeHtml(c.name)}</h2><div class="muted">${escapeHtml(c.phone||'Sem telefone')} ${c.city?'· '+escapeHtml(c.city):''}</div></div><span class="pill">Cliente</span></div><div class="client-kpis"><div class="card"><div class="muted">Última visita</div><b>${c.last||'—'}</b></div><div class="card"><div class="muted">Próximo</div><b>${c.next||'—'}</b></div><div class="card"><div class="muted">Visitas</div><b>${c.visits||0}</b></div><div class="card"><div class="muted">Crédito</div><b>${money(credit)}</b></div></div><div class="client-tabs"><button data-client-tab="resumo" onclick="switchClientProfileTab('resumo')">Resumo</button><button data-client-tab="agendamentos" onclick="switchClientProfileTab('agendamentos')">Agendamentos</button><button data-client-tab="comandas" onclick="switchClientProfileTab('comandas')">Comandas</button><button data-client-tab="creditos" onclick="switchClientProfileTab('creditos')">Créditos</button><button data-client-tab="pacotes" onclick="switchClientProfileTab('pacotes')">Pacotes${packs.length?' · '+packs.length:''}</button><button data-client-tab="retornos" onclick="switchClientProfileTab('retornos')">Retornos</button><button data-client-tab="historico" onclick="switchClientProfileTab('historico')">Histórico</button></div><div id="clientTabContent" class="client-tab-panel"></div>`,`<button class="btn btn-ghost" onclick="closeModal();openClientForm('${id}')">Editar cadastro</button><button class="btn btn-soft" onclick="toast('Contato preparado para ${escapeAttr(c.phone||'a cliente')}')">Contato</button><button class="btn btn-primary" onclick="newAppointmentForClient('${id}')">Novo agendamento</button>`);
 setTimeout(()=>{document.querySelector('#modalHost .modal')?.classList.add('modal-wide');switchClientProfileTab(tab)},0);
}
function newAppointmentForClient(id){closeModal();page='agenda';buildAdminNav();renderAgenda();setTimeout(()=>openReservation('','',id,agendaDate),40)}
function switchClientProfileTab(tab){
 document.querySelectorAll('[data-client-tab]').forEach(b=>b.classList.toggle('active',b.dataset.clientTab===tab));renderClientProfileTab(tab);
}
function renderClientProfileTab(tab){
 let id=window.clientProfileId,c=db.clients.find(x=>x.id===id),out=document.getElementById('clientTabContent');if(!c||!out)return;normalizeClient(c);
 if(tab==='resumo'){
   out.innerHTML=`<div class="client-section"><h3>Cadastro</h3><div class="form-grid"><div><b>Celular</b><div class="muted">${escapeHtml(c.phone||'—')}</div></div><div><b>Nascimento</b><div class="muted">${c.birthDate?new Date(c.birthDate+'T12:00:00').toLocaleDateString('pt-BR'):'—'}</div></div><div><b>CPF</b><div class="muted">${escapeHtml(c.cpf||'—')}</div></div><div><b>E-mail</b><div class="muted">${escapeHtml(c.email||'—')}</div></div><div><b>CEP / Bairro / Cidade</b><div class="muted">${escapeHtml(c.cep||'—')} · ${escapeHtml(c.neighborhood||'—')} · ${escapeHtml(c.city||'—')}</div></div><div><b>Como conheceu</b><div class="muted">${escapeHtml(c.source||'—')}</div></div><div><b>Origem do cadastro</b><div class="muted">${escapeHtml(c.origin||'—')}</div></div><div><b>Cadastrado por</b><div class="muted">${escapeHtml(c.createdBy||'—')}</div></div><div><b>Unidade do cadastro</b><div class="muted">${escapeHtml(db.units.find(u=>u.id===c.registrationUnit)?.name||'—')}</div></div></div>${c.notes?`<div class="inline-note" style="margin-top:14px">${escapeHtml(c.notes)}</div>`:''}</div><div class="client-section"><h3>Relacionamento</h3><div class="form-grid"><div><b>Crédito disponível</b><div class="muted">${money(clientCreditBalance(id))}</div></div><div><b>Pacotes ativos</b><div class="muted">${clientActivePackages(id).length}</div></div><div><b>Retornos pendentes</b><div class="muted">${(db.clientReturns||[]).filter(r=>r.clientId===id&&['Pendente','Contatado','Reagendado'].includes(r.status)).length}</div></div><div><b>Último contato</b><div class="muted">${latestClientContact(id)||'—'}</div></div></div></div>`;return;
 }
 if(tab==='agendamentos'){let a=clientAllAppointments(id);out.innerHTML=a.length?`<div class="client-table-wrap"><table class="client-table"><thead><tr><th>Data</th><th>Serviço</th><th>Profissional</th><th>Unidade</th><th>Status</th><th>Valor</th><th></th></tr></thead><tbody>${a.map(x=>`<tr><td><b>${formatDateBR(x.date)}</b><div class="muted">${x.time||''}</div></td><td>${escapeHtml(x.service||'—')}</td><td>${escapeHtml(x.professional||'—')}</td><td>${escapeHtml(db.units.find(u=>u.id===x.unitId)?.name||'—')}</td><td><span class="pill">${escapeHtml(x.status||'—')}</span></td><td>${money(x.value||0)}</td><td>${x.kind==='booking'?`<button class="btn btn-ghost btn-sm" onclick="openExistingBooking('${x.bookingId||x.id}')">Abrir</button>`:`<button class="btn btn-ghost btn-sm" onclick="showHistoricalAppointment('${x.id}')">Detalhes</button>`}</td></tr>`).join('')}</tbody></table></div>`:`<div class="client-empty">Nenhum agendamento encontrado.</div>`;return}
 if(tab==='comandas'){let rows=(db.clientCommands||[]).filter(x=>x.clientId===id).sort((a,b)=>b.date.localeCompare(a.date));out.innerHTML=rows.length?`<div class="client-table-wrap"><table class="client-table"><thead><tr><th>Comanda</th><th>Data</th><th>Unidade</th><th>Itens</th><th>Pagamento</th><th>Status</th><th>Total</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>#${escapeHtml(x.id.replace(/\D/g,''))}</b></td><td>${formatDateBR(x.date)}</td><td>${escapeHtml(db.units.find(u=>u.id===x.unitId)?.name||'—')}</td><td>${x.status==='Aberta'?(normalizeCommand(x).lines.map(l=>escapeHtml(l.name)).join('<br>')||'—'):(x.items||[]).map(escapeHtml).join('<br>')}</td><td>${(x.payments||[]).map(escapeHtml).join('<br>')||'—'}</td><td><span class="pill">${escapeHtml(x.status)}</span></td><td><b>${money(x.status==='Aberta'?commandGrossTotal(normalizeCommand(x)):x.total)}</b></td><td>${x.status==='Aberta'?`<button class="btn btn-ghost btn-sm" onclick="openCommand('${x.id}')">Abrir</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:`<div class="client-empty">Nenhuma comanda registrada para esta cliente.</div>`;return}
 if(tab==='creditos'){let rows=(db.clientCreditMovements||[]).filter(x=>x.clientId===id).sort((a,b)=>(b.createdAt||b.date).localeCompare(a.createdAt||a.date)),bal=clientCreditBalance(id);out.innerHTML=`<div class="client-balance"><div><div class="muted">Saldo disponível</div><strong>${money(bal)}</strong></div><button class="btn btn-primary" onclick="openAddClientCredit('${id}')">+ Adicionar crédito</button></div><div class="inline-note" style="margin-bottom:14px"><b>Integração financeira:</b> créditos pagos e sinais geram entrada no Caixa e no Financeiro. Cortesias, ajustes e estornos para saldo não simulam nova entrada de dinheiro.</div>${rows.length?`<div class="client-table-wrap"><table class="client-table"><thead><tr><th>Data</th><th>Movimento</th><th>Valor</th><th>Pagamento</th><th>Unidade</th><th>Responsável</th><th>Observação</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${formatDateBR(x.date)}</td><td>${escapeHtml(x.type)}</td><td style="font-weight:750;color:${x.amount>=0?'var(--ok)':'var(--danger)'}">${x.amount>=0?'+ ':''}${money(x.amount)}</td><td>${escapeHtml(x.paymentMethod||'—')}${x.financialAccount?' · '+escapeHtml(x.financialAccount):''}</td><td>${escapeHtml(db.units.find(u=>u.id===x.unitId)?.name||'—')}</td><td>${escapeHtml(x.user||'Sistema')}</td><td>${escapeHtml(x.note||'—')}</td></tr>`).join('')}</tbody></table></div>`:`<div class="client-empty">Nenhuma movimentação de crédito.</div>`}`;return}
 if(tab==='pacotes'){let rows=(db.clientPackages||[]).filter(x=>x.clientId===id);out.innerHTML=rows.length?rows.map(x=>{let used=Math.max(0,x.totalUnits-x.remainingUnits),pct=x.totalUnits?Math.round(used/x.totalUnits*100):0;return `<div class="package-card"><div style="display:flex;justify-content:space-between;gap:12px"><div><b>${escapeHtml(x.name)}</b><div class="muted">Comprado em ${formatDateBR(x.purchasedAt)} · Válido até ${formatDateBR(x.expiresAt)}</div></div><span class="pill">${escapeHtml(x.status)}</span></div><div style="margin-top:12px"><b>${x.remainingUnits} de ${x.totalUnits}</b> utilizações restantes</div><div class="progress"><span style="width:${pct}%"></span></div><div class="muted" style="margin-top:7px">${escapeHtml(x.details||'')}</div></div>`}).join(''):`<div class="client-empty">Nenhum pacote comprado.</div>`;return}
 if(tab==='retornos'){let rows=(db.clientReturns||[]).filter(x=>x.clientId===id).sort((a,b)=>a.dueDate.localeCompare(b.dueDate));out.innerHTML=rows.length?rows.map(x=>`<div class="return-card"><div style="display:flex;justify-content:space-between;gap:12px"><div><b>${escapeHtml(x.category)} · ${escapeHtml(x.service)}</b><div class="muted">Previsto para ${formatDateBR(x.dueDate)} · Profissional original: ${escapeHtml(x.originalProfessional||'—')}</div></div><span class="pill">${escapeHtml(x.status)}</span></div>${x.lastContact?`<div class="muted" style="margin-top:8px">Último contato: ${formatDateBR(x.lastContact)}</div>`:''}${x.note?`<div class="inline-note">${escapeHtml(x.note)}</div>`:''}<div class="mini-actions"><button class="btn btn-soft btn-sm" onclick="markReturnContact('${x.id}')">Registrar contato</button>${x.status!=='Retornado'?`<button class="btn btn-ghost btn-sm" onclick="markReturnClosed('${x.id}')">Encerrar / Não aplicável</button>`:''}</div></div>`).join(''):`<div class="client-empty">Nenhum ciclo de retorno para esta cliente.</div>`;return}
 if(tab==='historico'){let events=buildClientTimeline(id);out.innerHTML=events.length?`<div class="client-section"><h3>Linha do tempo</h3><div class="timeline">${events.map(e=>`<div class="timeline-item"><b>${escapeHtml(e.title)}</b><div class="muted">${formatDateBR(e.date)}${e.time?' · '+e.time:''} · ${escapeHtml(e.detail||'')}</div></div>`).join('')}</div></div>`:`<div class="client-empty">Ainda não há histórico.</div>`}
}
function formatDateBR(v){if(!v)return'—';let p=String(v).slice(0,10).split('-');return p.length===3?`${p[2]}/${p[1]}/${p[0]}`:v}
function latestClientContact(id){let rs=(db.clientReturns||[]).filter(x=>x.clientId===id&&x.lastContact).sort((a,b)=>b.lastContact.localeCompare(a.lastContact));return rs[0]?formatDateBR(rs[0].lastContact):''}
function showHistoricalAppointment(id){let x=(db.clientAppointments||[]).find(a=>a.id===id);if(!x)return;modal('Detalhes do atendimento',`<div class="booking-summary"><div class="row"><span>Data</span><b>${formatDateBR(x.date)} · ${x.time||''}</b></div><div class="row"><span>Serviço</span><b>${escapeHtml(x.service)}</b></div><div class="row"><span>Profissional</span><b>${escapeHtml(x.professional)}</b></div><div class="row"><span>Unidade</span><b>${escapeHtml(db.units.find(u=>u.id===x.unitId)?.name||'—')}</b></div><div class="row"><span>Status</span><b>${escapeHtml(x.status)}</b></div><div class="row"><span>Valor</span><b>${money(x.value||0)}</b></div></div>`,`<button class="btn btn-primary" onclick="closeModal();openClient('${x.clientId}','agendamentos')">Voltar à cliente</button>`)}
function creditCreatesCash(type){return ['Crédito pago pela cliente','Sinal recebido'].includes(type)}
function creditAccountOptions(unitId){let rows=(db.financialAccounts||[]).filter(x=>x.unitId===unitId);return rows.map(x=>`<option value="${x.id}">${escapeHtml(x.name)}</option>`).join('')}
function refreshCreditFinancialFields(){let type=document.getElementById('creditType')?.value||'',box=document.getElementById('creditFinancialFields'),msg=document.getElementById('creditImpact');if(!box)return;let paid=creditCreatesCash(type);box.style.display=paid?'contents':'none';if(msg)msg.innerHTML=paid?'<b>Este lançamento gera entrada real.</b> Ao salvar, o sistema registra o crédito da cliente + entrada no Caixa + lançamento no Financeiro. A receita do serviço só será apropriada quando o crédito for utilizado.':'<b>Este lançamento não gera nova entrada de dinheiro.</b> Ele movimenta somente o saldo de crédito da cliente e mantém o histórico da operação.'}
function refreshCreditAccounts(){let unitId=document.getElementById('creditUnit')?.value||document.getElementById('unitPicker')?.value||'',sel=document.getElementById('creditAccount');if(sel)sel.innerHTML=unitId?creditAccountOptions(unitId):'<option value="">Selecione a unidade</option>'}
function openAddClientCredit(clientId){let defaultUnit=document.getElementById('unitPicker')?.value||'';if(defaultUnit&&!(db.units||[]).some(u=>u.id===defaultUnit&&u.active!==false))defaultUnit='';modal('Adicionar crédito',`<div class="inline-note" id="creditImpact" style="margin-bottom:14px"></div><div class="form-grid"><div class="field"><label class="required">Tipo</label><select id="creditType" onchange="refreshCreditFinancialFields()"><option>Crédito pago pela cliente</option><option>Sinal recebido</option><option>Crédito promocional/cortesia</option><option>Ajuste</option><option>Estorno/devolução</option></select></div><div class="field"><label class="required">Valor</label><input id="creditAmount" type="number" min="0.01" step="0.01" placeholder="0,00"></div><div id="creditFinancialFields" style="display:contents"><div class="field"><label class="required">Forma de pagamento</label><select id="creditPaymentMethod">${(db.paymentMethods||[]).map(x=>`<option value="${x.id}">${escapeHtml(x.name)}</option>`).join('')}</select></div><div class="field"><label class="required">Unidade</label><select id="creditUnit" onchange="refreshCreditAccounts()">${defaultUnit?'':'<option value="" selected>Selecione a unidade</option>'}${db.units.filter(u=>u.active!==false).map(u=>`<option value="${u.id}" ${u.id===defaultUnit?'selected':''}>${escapeHtml(u.name)}</option>`).join('')}</select></div><div class="field full"><label class="required">Conta / destino</label><select id="creditAccount">${defaultUnit?creditAccountOptions(defaultUnit):'<option value="">Selecione a unidade</option>'}</select></div></div><div class="field full"><label>Relacionado a um agendamento?</label><select id="creditAppointment"><option value="">Não vincular</option>${clientAllAppointments(clientId).filter(a=>['Agendado','Confirmado','Aguardando confirmação'].includes(a.status)).map(a=>`<option value="${a.id}">${formatDateBR(a.date)} ${a.time||''} · ${escapeHtml(a.service||'Atendimento')}</option>`).join('')}</select></div><div class="field full"><label>Observação</label><textarea id="creditNote" rows="3" placeholder="Opcional"></textarea></div></div>`,`<button class="btn btn-ghost" onclick="closeModal();openClient('${clientId}','creditos')">Cancelar</button><button class="btn btn-primary" onclick="saveClientCredit('${clientId}')">Salvar crédito</button>`);setTimeout(refreshCreditFinancialFields,0)}
function saveClientCredit(clientId){let v=typeof roundMoney==='function'?roundMoney(Number(document.getElementById('creditAmount')?.value||0)):Math.round(Number(document.getElementById('creditAmount')?.value||0)*100)/100;if(!(v>0)){toast('Informe um valor válido');return}let type=document.getElementById('creditType')?.value||'Ajuste',paid=creditCreatesCash(type),unitId=paid?(document.getElementById('creditUnit')?.value||''):null,pmId=paid?(document.getElementById('creditPaymentMethod')?.value||''):null,accountId=paid?(document.getElementById('creditAccount')?.value||''):null;if(paid&&(!(db.units||[]).some(u=>u.id===unitId&&u.active!==false)||!pmId||!accountId)){toast('Informe forma de pagamento, unidade válida e conta/destino');return}let pm=(db.paymentMethods||[]).find(x=>x.id===pmId),fa=(db.financialAccounts||[]).find(x=>x.id===accountId);if(paid&&(!fa||fa.active===false||fa.unitId!==unitId)){toast('Selecione uma conta/destino válida da unidade informada');return}let now=new Date(),movement={id:'cr'+Date.now(),clientId,date:localDateISO(now),createdAt:now.toISOString(),type,amount:v,note:document.getElementById('creditNote')?.value.trim()||'',user:currentUserName(),unitId:unitId||null,paymentMethod:pm?.name||'',financialAccount:fa?.name||'',appointmentId:document.getElementById('creditAppointment')?.value||null,financialImpact:paid};db.clientCreditMovements.push(movement);if(paid){db.demoCashMovements.push({id:'cm'+Date.now(),clientId,unitId,amount:v,paymentMethod:pm?.name||'',account:fa?.name||'',type:type==='Sinal recebido'?'Sinal recebido':'Crédito recebido',date:movement.date,createdAt:now.toISOString(),user:currentUserName(),processorFee:0});db.demoFinancialEntries.push({id:'fe'+Date.now(),clientId,unitId,amount:v,nature:type==='Sinal recebido'?'Sinais recebidos':'Créditos recebidos',account:fa?.name||'',date:movement.date,origin:'Crédito do cliente'});}save();closeModal();openClient(clientId,'creditos');toast(paid?'Crédito salvo · Caixa e Financeiro atualizados':'Crédito salvo sem entrada financeira')}
function markReturnContact(returnId){let r=(db.clientReturns||[]).find(x=>x.id===returnId);if(!r)return;r.status='Contatado';r.lastContact=localDateISO();save();renderClientProfileTab('retornos');toast('Contato registrado')}
