function buildClientTimeline(id){let c=db.clients.find(x=>x.id===id),events=[];if(c?.createdAt)events.push({date:c.createdAt,title:'Cadastro criado',detail:`${c.origin||'Origem não informada'} · ${c.createdBy||'Sistema'}`});clientAllAppointments(id).forEach(a=>events.push({date:a.date,time:a.time,title:`Agendamento / atendimento: ${a.service}`,detail:`${a.status||''} · ${a.professional||''}`}));(db.clientCommands||[]).filter(x=>x.clientId===id).forEach(x=>events.push({date:x.date,title:`Comanda ${x.id} · ${money(x.status==='Aberta'?commandGrossTotal(normalizeCommand(x)):x.total)}`,detail:x.status}));(db.clientCreditMovements||[]).filter(x=>x.clientId===id).forEach(x=>events.push({date:x.date,title:`${x.type}: ${x.amount>=0?'+ ':''}${money(x.amount)}`,detail:x.note||x.user||''}));(db.clientReturns||[]).filter(x=>x.clientId===id).forEach(x=>events.push({date:x.lastContact||x.dueDate,title:`Retorno ${x.status}`,detail:`${x.category} · previsto ${formatDateBR(x.dueDate)}`}));return events.sort((a,b)=>(b.date+(b.time||'')).localeCompare(a.date+(a.time||'')))}
