 let services=db.services.filter(s=>s.active),srv=services.find(s=>!proId||professionalCanDo(proId,s.id))||services[0];let pros=srv?eligiblePros(srv.id,unitId):[];let pid=proId&&srv&&professionalCanDo(proId,srv.id)?proId:(pros[0]?.id||'');return {serviceId:srv?.id||'',service:srv?.name||'',pro:pid,time:time||'11:00',duration:srv?.duration||45,price:srv?.price||0,preference:false,forceFit:false}
