function syncResDraftFromDom(){if(!window.resDraft)return;let d=document.getElementById('rDate'),st=document.getElementById('rStatus');if(d)resDraft.date=d.value;if(st)resDraft.status=st.value;document.querySelectorAll('.res-line').forEach((row,i)=>{if(!resDraft.items[i])return;let sid=row.querySelector('.res-service')?.value||'',srv=db.services.find(s=>s.id===sid);Object.assign(resDraft.items[i],{serviceId:sid,service:srv?.name||'',pro:row.querySelector('.res-pro')?.value||'',duration:Number(row.querySelector('.res-duration')?.value||srv?.duration||45),time:row.querySelector('.res-time')?.value||'',price:Number(row.querySelector('.res-price')?.value||srv?.price||0),preference:!!row.querySelector('.res-pref')?.checked,forceFit:!!row.querySelector('.res-force')?.checked})})}
