function renderReservationModal(){
 const uid=unitPicker.value||'',sel=resDraft?.clientId?db.clients.find(c=>c.id===resDraft.clientId):null;
 let rows=(resDraft.items||[]).map((it,i)=>`<tr class="res-line"><td><select class="res-service" onchange="resLineServiceChanged(${i},this.value)">${db.services.filter(s=>s.active).map(s=>`<option value="${s.id}" ${s.id===it.serviceId?'selected':''}>${escapeHtml(s.name)}</option>`).join('')}</select></td><td><select class="res-pro">${reservationProOptions(it.serviceId,it.pro,uid)}</select></td><td><input class="res-duration" type="number" min="1" value="${it.duration}" oninput="updateReservationEndFromRow(this,'.res-time','.res-duration')"></td><td><input class="res-time" type="time" value="${it.time}" oninput="resLineTimeInput(${i},this)"></td><td class="end-cell">${addMinutesTime(it.time,it.duration)}</td><td><input class="res-price" type="number" min="0" step="0.01" value="${Number(it.price||0)}"></td><td><label class="pref-check"><input class="res-pref" type="checkbox" ${it.preference?'checked':''}> Preferência</label></td><td><label class="pref-check"><input class="res-force" type="checkbox" ${it.forceFit?'checked':''}> Forçar encaixe</label></td><td>${resDraft.items.length>1?`<button class="btn btn-danger btn-sm" onclick="removeReservationLine(${i})">×</button>`:''}</td></tr>`).join('');
 modal('Nova reserva',`<div class="form-tabs"><button class="active">Reserva</button><button disabled style="opacity:.45">Informações</button></div><div class="reservation-client">${sel?`<div><b>${escapeHtml(sel.name)}</b><div class="muted">${escapeHtml(sel.phone||'')}</div></div><div class="spacer"></div><button class="btn btn-ghost btn-sm" onclick="resDraft.clientId='';renderReservationModal()">Trocar</button>`:`<div class="field" style="flex:1"><label>Cliente</label><input id="rClientSearch" placeholder="Buscar por nome, telefone ou CPF" oninput="reservationClientSearch()"><div id="rClientResults"></div><button class="btn btn-soft btn-sm" style="margin-top:8px" onclick="openQuickClientFromReservation()">+ Nova cliente</button></div>`}</div><div class="reservation-meta"><div class="field"><label>Data</label><input id="rDate" type="date" value="${resDraft.date||agendaDate}"></div><div class="field"><label>Status</label><select id="rStatus">${['Agendado','Aguardando confirmação','Confirmado','Em atendimento','Concluído','Cancelado','Faltou'].map(x=>`<option ${x===resDraft.status?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="reservation-lines"><table class="reservation-table"><thead><tr><th>Serviço</th><th>Profissional</th><th>Tempo</th><th>Início</th><th>Fim</th><th>Valor</th><th>Preferência</th><th>Encaixe</th><th></th></tr></thead><tbody>${rows}</tbody></table></div><div class="reservation-actions"><button class="btn btn-soft btn-sm" onclick="addReservationLine()">+ Adicionar serviço</button></div><div class="force-fit-help"><b>Forçar encaixe</b> permite sobrepor este serviço a outro atendimento da mesma profissional. O sistema continua validando se a profissional executa o serviço.</div>`,`<button class="btn btn-ghost" onclick="closeModal()">Cancelar</button><button class="btn btn-primary" onclick="saveReservation()">Salvar</button>`);
 setTimeout(()=>{document.querySelector('#modalHost .modal')?.classList.add('modal-wide');if(!sel&&resDraft.clientSearch){rClientSearch.value=resDraft.clientSearch;reservationClientSearch()}},0)
}
function resLineServiceChanged(i,val){syncResDraftFromDom();let srv=db.services.find(s=>s.id===val),it=resDraft.items[i];it.serviceId=val;it.service=srv?.name||'';it.duration=srv?.duration||45;it.price=srv?.price||0;if(!professionalCanDo(it.pro,val))it.pro=eligiblePros(val,unitPicker.value||'')[0]?.id||'';renderReservationModal()}
function updateReservationEndFromRow(el,timeSelector,durationSelector){let row=el.closest('tr');if(!row)return;let t=row.querySelector(timeSelector)?.value||'',d=Number(row.querySelector(durationSelector)?.value||0),cell=row.querySelector('.end-cell');if(cell&&/^\d{2}:\d{2}$/.test(t)&&d>0)cell.textContent=addMinutesTime(t,d)}
