function addReservationLine(){syncResDraftFromDom();let prev=resDraft.items[resDraft.items.length-1],start=prev?addMinutesTime(prev.time,prev.duration):'11:00';resDraft.items.push(defaultReservationItem('',start,unitPicker.value||''));renderReservationModal()}
