function reservationClientSearch(){let out=document.getElementById('rClientResults'),inp=document.getElementById('rClientSearch');if(!out||!inp)return;resDraft.clientSearch=inp.value;let q=normName(inp.value);if(q.length<2&&digits(inp.value).length<4){out.innerHTML='';return}let matches=db.clients.filter(c=>normName(c.name).includes(q)||digits(c.phone).includes(digits(inp.value))||digits(c.cpf).includes(digits(inp.value))).slice(0,6);out.innerHTML=`<div class="client-results">${matches.length?matches.map(c=>`<div class="client-result"><div><b>${escapeHtml(c.name)}</b><div class="muted">${escapeHtml(c.phone||'')} ${c.birthDate?'· '+new Date(c.birthDate+'T12:00:00').toLocaleDateString('pt-BR'):''}</div></div><button class="btn btn-soft btn-sm" onclick="selectReservationClient('${c.id}')">Selecionar</button></div>`).join(''):'<div class="client-result"><div><b>Nenhum cadastro encontrado</b><div class="muted">Você pode cadastrar a cliente sem sair da Agenda.</div></div><button class="btn btn-primary btn-sm" onclick="openQuickClientFromReservation()">+ Nova cliente</button></div>'}</div>`}
