// ===== V29 · COMBOS AUTOMÁTICOS =====
// Um combo é uma regra comercial: quando todos os serviços componentes aparecem na mesma visita
// (mesma cliente + data + unidade), o preço fixo do combo substitui a soma dos preços avulsos.
if(!Array.isArray(db.combos))db.combos=[];
function normalizeCombo(c){
 if(!Array.isArray(c.serviceIds))c.serviceIds=[];
 if(c.active===undefined)c.active=true;
 if(c.autoApply===undefined)c.autoApply=true;
 if(c.price===undefined)c.price=0;
 if(!c.name)c.name='Combo';
 return c
}
(db.combos||[]).forEach(normalizeCombo);
if(storageState.allowLegacyDemoFixes&&!db.combos.some(c=>c.id==='combo_hands_feet'))db.combos.push(normalizeCombo({id:'combo_hands_feet',name:'Mão + Pé',serviceIds:['s1','s3'],price:65,active:true,autoApply:true}));
// Ajusta somente os valores demonstrativos antigos para reproduzir o exemplo real informado (40 + 40 = 65).
if(storageState.allowLegacyDemoFixes&&!db.comboPricingMigratedV29){
 let manicure=db.services.find(s=>s.id==='s1'),pedicure=db.services.find(s=>s.id==='s3');
 if(manicure&&Number(manicure.price)===45)manicure.price=40;
 if(pedicure&&Number(pedicure.price)===55)pedicure.price=40;
 (db.bookings||[]).forEach(b=>{normalizeBooking(b);(b.items||[]).forEach(it=>{if(it.serviceId==='s1'&&Number(it.price)===45)it.price=40;if(it.serviceId==='s3'&&Number(it.price)===55)it.price=40})});
 db.comboPricingMigratedV29=true;
}
function activeCombos(){return (db.combos||[]).map(normalizeCombo).filter(c=>c.active&&c.autoApply&&c.serviceIds.length>=2)}
function comboRegularPrice(combo){return (combo.serviceIds||[]).reduce((a,id)=>a+Number(db.services.find(s=>s.id===id)?.price||0),0)}
function comboServicesLabel(combo){return (combo.serviceIds||[]).map(id=>db.services.find(s=>s.id===id)?.name||id).join(' + ')}
function comboApplicationsFromEntries(entries=[]){
 // Expande ocorrências para permitir, no futuro, duas unidades do mesmo serviço sem reaproveitar a mesma linha.
 let pool=[];entries.forEach((e,idx)=>{let qty=Math.max(1,Math.floor(Number(e.qty||1)));for(let n=0;n<qty;n++)pool.push({...e,_occ:`${e.key||idx}:${n}`,amount:Math.max(0,Number(e.amount||0))/qty})});
 let used=new Set(),apps=[];
 // Prioriza maior economia para evitar que um mesmo serviço seja consumido por dois combos concorrentes.
 let combos=activeCombos().map(c=>({...c,_saving:Math.max(0,comboRegularPrice(c)-Number(c.price||0))})).sort((a,b)=>b._saving-a._saving);
 for(const combo of combos){
  while(true){
   let picks=[],temp=new Set();
   for(const sid of combo.serviceIds){let found=pool.find(e=>e.serviceId===sid&&!used.has(e._occ)&&!temp.has(e._occ));if(!found){picks=[];break}picks.push(found);temp.add(found._occ)}
   if(!picks.length)break;
   let base=picks.reduce((a,e)=>a+Math.max(0,Number(e.amount||0)),0),fixed=Math.max(0,Number(combo.price||0)),discount=Math.max(0,base-fixed);
   // Não usamos o combo para aumentar preço quando descontos manuais já deixaram os itens abaixo do valor fixo.
   if(discount<=.009)break;
   picks.forEach(e=>used.add(e._occ));apps.push({comboId:combo.id,name:combo.name,serviceIds:[...combo.serviceIds],base,price:fixed,discount,picks:picks.map(e=>e.key)});
  }
 }
 return apps
}
function commandComboApplications(c){
 normalizeCommand(c);let entries=(c.lines||[]).filter(l=>l.type==='service'&&l.serviceId).map(l=>({key:l.id,serviceId:l.serviceId,qty:l.qty||1,amount:commandLineTotal(l)}));return comboApplicationsFromEntries(entries)
}
function commandComboDiscount(c){return commandComboApplications(c).reduce((a,x)=>a+x.discount,0)}
// Sobrescreve apenas os cálculos agregados: descontos manuais continuam nas linhas, combo entra como ajuste automático da visita.
commandGrossTotal=function(c){normalizeCommand(c);let lineNet=c.lines.reduce((sum,l)=>sum+commandLineTotal(l),0);return Math.max(0,lineNet-commandComboDiscount(c))};
commandDiscountTotal=function(c){normalizeCommand(c);let manual=c.lines.reduce((sum,l)=>sum+Math.max(0,Number(l.discount||0)),0);return manual+commandComboDiscount(c)};

function comboEntriesForVisit(clientId,unitId,date,replaceBookingId='',draftBooking=null){
 let entries=[];
 (db.bookings||[]).forEach(b=>{normalizeBooking(b);if(b.id===replaceBookingId)return;if(b.clientId!==clientId||b.unit!==unitId||b.date!==date||['Cancelado','Faltou','Bloqueado'].includes(b.status))return;(b.items||[]).forEach((it,i)=>entries.push({key:`${b.id}:${i}`,serviceId:it.serviceId,qty:1,amount:Number(it.price||0)}))});
 if(draftBooking&&draftBooking.status!=='Cancelado'&&draftBooking.status!=='Faltou'){(draftBooking.items||[]).forEach((it,i)=>entries.push({key:`draft:${i}`,serviceId:it.serviceId,qty:1,amount:Number(it.price||0)}))}
 return entries
}
function comboVisitSummaryForBooking(id){
 let b=db.bookings.find(x=>x.id===id);if(!b)return null;normalizeBooking(b);let draft=(window.editBookingId===id&&window.editBookingDraft)?window.editBookingDraft:b,entries=comboEntriesForVisit(b.clientId,b.unit,draft.date||b.date,id,draft),apps=comboApplicationsFromEntries(entries);if(!apps.length)return null;let base=entries.reduce((a,e)=>a+Math.max(0,Number(e.amount||0)),0),discount=apps.reduce((a,x)=>a+x.discount,0);return {apps,base,discount,total:Math.max(0,base-discount)}
}
function comboAppliedHtml(apps,total=null,context='visita'){
 if(!apps?.length)return '';
 let details=apps.map(a=>`<div><b>${escapeHtml(a.name)}</b> · ${money(a.price)} <span class="combo-badge ok">economia ${money(a.discount)}</span><div class="muted">${escapeHtml(comboServicesLabel(db.combos.find(c=>c.id===a.comboId)||{serviceIds:a.serviceIds}))}</div></div>`).join('<div style="height:7px"></div>');
 return `<div class="combo-applied"><div class="icon">%</div><div style="flex:1"><b>Combo aplicado automaticamente</b><div class="muted">Os serviços foram agendados separadamente, mas pertencem à mesma ${context}. O sistema mantém os serviços/profissionais individuais e corrige apenas o valor comercial.</div><div style="margin-top:8px">${details}</div>${total!==null?`<div style="margin-top:8px;font-size:12px"><b>Total da visita: ${money(total)}</b></div>`:''}</div></div>`
}

// Serviços + Combos na mesma área administrativa.
const _renderServicesV28=renderServices;
renderServices=function(){
 _renderServicesV28();subbar.textContent='Categorias · Serviços · Combos · Regras de retorno';
 let head=adminPage.querySelector('.page-head'),primary=head?.querySelector('.btn-primary');if(primary&&!head.querySelector('[data-new-combo]'))primary.insertAdjacentHTML('beforebegin',`<button class="btn btn-soft" data-new-combo onclick="openComboForm()">+ Novo combo</button>`);
 let combos=(db.combos||[]).map(normalizeCombo);let rows=combos.map(c=>{let regular=comboRegularPrice(c),saving=Math.max(0,regular-Number(c.price||0));return `<tr><td><b>${escapeHtml(c.name)}</b><div class="muted" style="font-size:11px;margin-top:3px">${escapeHtml(comboServicesLabel(c))}</div></td><td>${money(regular)}</td><td><b>${money(c.price)}</b></td><td class="combo-economy">${saving?money(saving):'—'}</td><td>${c.autoApply?'Sim':'Não'}</td><td class="${c.active?'status-on':'status-off'}">${c.active?'Ativo':'Inativo'}</td><td class="row-actions"><button class="btn btn-ghost btn-sm" onclick="openComboForm('${c.id}')">Editar</button><button class="btn btn-danger btn-sm" onclick="toggleCombo('${c.id}')">${c.active?'Desativar':'Ativar'}</button></td></tr>`}).join('')||'<tr><td colspan="7" class="muted">Nenhum combo cadastrado.</td></tr>';
 adminPage.insertAdjacentHTML('beforeend',`<div class="combo-section"><div class="combo-head"><div><h2>Combos</h2><p class="muted">Regras de preço que são reconhecidas automaticamente quando os serviços aparecem na mesma visita.</p></div><div class="spacer"></div></div><div class="table-card"><table class="table"><thead><tr><th>Combo</th><th>Avulso</th><th>Preço combo</th><th>Economia</th><th>Automático</th><th>Status</th><th></th></tr></thead><tbody>${rows}</tbody></table></div><div class="combo-rule-note">Exemplo: Manicure R$ 40 + Pedicure R$ 40 → Combo Mão + Pé R$ 65. Os dois serviços continuam separados na Agenda para horário e profissional, mas a Comanda reconhece o combo e cobra R$ 65.</div></div>`)
};
function openComboForm(id=''){
 let c=id?db.combos.find(x=>x.id===id):null;c=normalizeCombo(c?structuredClone(c):{id:'',name:'',serviceIds:[],price:0,active:true,autoApply:true});
 let options=db.services.filter(s=>s.active).map(s=>`<label class="combo-service-option"><input type="checkbox" class="combo-service-check" value="${s.id}" ${c.serviceIds.includes(s.id)?'checked':''} onchange="refreshComboPreview()"><span><b>${escapeHtml(s.name)}</b><div class="muted" style="font-size:10px">${money(s.price)}</div></span></label>`).join('');
 modal(id?'Editar combo':'Novo combo',`<div class="form-grid"><div class="field full"><label>Nome do combo *</label><input id="comboName" value="${escapeAttr(c.name)}" placeholder="Ex.: Mão + Pé"></div><div class="field full"><label>Serviços que formam o combo *</label><div class="combo-service-list">${options}</div></div><div class="field"><label>Preço fixo do combo *</label><input id="comboPrice" type="number" min="0" step="0.01" value="${Number(c.price||0)}" oninput="refreshComboPreview()"></div><div class="field"><label>Status</label><select id="comboActive"><option value="1" ${c.active?'selected':''}>Ativo</option><option value="0" ${!c.active?'selected':''}>Inativo</option></select></div><div class="field full"><label class="check"><input id="comboAuto" type="checkbox" ${c.autoApply?'checked':''}> Aplicar automaticamente quando todos os serviços estiverem na mesma visita</label></div></div><div id="comboPreview" class="inline-note" style="margin-top:12px"></div>`,`<button class="btn btn-ghost" onclick="closeModal()">Cancelar</button><button class="btn btn-primary" onclick="saveCombo('${id}')">Salvar combo</button>`);setTimeout(refreshComboPreview,0)
}
function refreshComboPreview(){let ids=[...document.querySelectorAll('.combo-service-check:checked')].map(x=>x.value),regular=ids.reduce((a,id)=>a+Number(db.services.find(s=>s.id===id)?.price||0),0),price=Math.max(0,Number(document.getElementById('comboPrice')?.value||0)),el=document.getElementById('comboPreview');if(!el)return;el.innerHTML=ids.length<2?'Selecione pelo menos dois serviços.':`Preço avulso: <b>${money(regular)}</b> · Combo: <b>${money(price)}</b> · Economia: <b>${money(Math.max(0,regular-price))}</b>`}
function saveCombo(id=''){let name=document.getElementById('comboName')?.value.trim()||'',serviceIds=[...document.querySelectorAll('.combo-service-check:checked')].map(x=>x.value),price=Math.max(0,Number(document.getElementById('comboPrice')?.value||0));if(!name){toast('Informe o nome do combo');return}if(serviceIds.length<2){toast('Selecione pelo menos dois serviços');return}if(!(price>0)){toast('Informe o preço do combo');return}let c=id?db.combos.find(x=>x.id===id):null;if(!c){c={id:'combo'+Date.now()};db.combos.push(c)}Object.assign(c,{name,serviceIds,price,active:document.getElementById('comboActive')?.value==='1',autoApply:!!document.getElementById('comboAuto')?.checked});normalizeCombo(c);save();closeModal();renderServices();toast(id?'Combo atualizado ✓':'Combo cadastrado ✓')}
function toggleCombo(id){let c=db.combos.find(x=>x.id===id);if(!c)return;c.active=!c.active;save();renderServices();toast(c.active?'Combo ativado':'Combo desativado')}

// Ao abrir uma reserva, mostramos a regra comercial sem poluir os cartões da Agenda.
const _renderExistingBookingModalV28=renderExistingBookingModal;
renderExistingBookingModal=function(tab='reserva'){
 _renderExistingBookingModalV28(tab);
 if(tab!=='reserva')return;
 setTimeout(()=>{let sum=comboVisitSummaryForBooking(window.editBookingId);if(!sum)return;let anchor=document.querySelector('#modalHost .reservation-lines');if(anchor&&!document.querySelector('#modalHost .combo-applied'))anchor.insertAdjacentHTML('beforebegin',comboAppliedHtml(sum.apps,sum.total,'visita'))},0)
};

// Mantém a Comanda em duas linhas de serviço (para comissão/profissional) e aplica o desconto do combo no total.
const _renderCommandModalV28=renderCommandModal;
renderCommandModal=function(id){
 _renderCommandModalV28(id);
 setTimeout(()=>{let c=db.clientCommands.find(x=>x.id===id);if(!c)return;let apps=commandComboApplications(c);if(!apps.length)return;let anchor=document.querySelector('#modalHost .command-sync-note');if(anchor&&!document.querySelector('#modalHost .combo-applied'))anchor.insertAdjacentHTML('afterend',comboAppliedHtml(apps,commandGrossTotal(c),'comanda'))},0)
};
// Ao sincronizar itens novos vindos da Agenda, o preço do combo é recalculado automaticamente pelo total.
const _syncCommandAgendaItemsV28=syncCommandAgendaItems;
syncCommandAgendaItems=function(c){let out=_syncCommandAgendaItemsV28(c);c.comboApplications=commandComboApplications(c).map(a=>({comboId:a.comboId,name:a.name,price:a.price,discount:a.discount,picks:a.picks}));return out};
const _saveReservationV28=saveReservation;
saveReservation=function(){let ctx=window.resDraft?{clientId:resDraft.clientId,appendToBookingId:resDraft.appendToBookingId||'',date:resDraft.date}:null;_saveReservationV28();if(!ctx?.clientId)return;let candidate=(db.bookings||[]).filter(b=>b.clientId===ctx.clientId&&b.date===ctx.date&&!['Cancelado','Faltou','Bloqueado'].includes(b.status)).sort((a,b)=>String(b.id).localeCompare(String(a.id)))[0];if(candidate){let sum=comboVisitSummaryForBooking(candidate.id);if(sum)toast(`Combo ${sum.apps.map(a=>a.name).join(' + ')} reconhecido automaticamente · total da visita ${money(sum.total)} ✓`)}};
const _saveExistingBookingV28=saveExistingBooking;
saveExistingBooking=function(){let id=window.editBookingId;_saveExistingBookingV28();if(id){let sum=comboVisitSummaryForBooking(id);if(sum)toast(`Combo aplicado automaticamente · total da visita ${money(sum.total)} ✓`)}};
const _saveCommandOnlyServiceV28=saveCommandOnlyService;
saveCommandOnlyService=function(cmdId){_saveCommandOnlyServiceV28(cmdId);let c=db.clientCommands.find(x=>x.id===cmdId);if(c){c.comboApplications=commandComboApplications(c);save()}};
const _finalizeCommandPaymentV28=finalizeCommandPayment;
finalizeCommandPayment=function(cmdId){let c=db.clientCommands.find(x=>x.id===cmdId);if(c){c.comboApplications=commandComboApplications(c).map(a=>({comboId:a.comboId,name:a.name,price:a.price,discount:a.discount,picks:a.picks}));save()}return _finalizeCommandPaymentV28(cmdId)};

save();

renderPublic();


// ===== V32: FINANCEIRO CONSOLIDADO =====
let financeTab='entries';
let financeToday=localDateISO(new Date());
let financeMonthStart=financeToday.slice(0,8)+'01';
if(!Array.isArray(db.financeCategories))db.financeCategories=[
 {id:'fc_sales',name:'Receita de serviços',kind:'income',dre:true},
 {id:'fc_products',name:'Venda de produtos',kind:'income',dre:true},
 {id:'fc_other_income',name:'Outras receitas operacionais',kind:'income',dre:true},
 {id:'fc_food',name:'Copa e alimentação',kind:'expense',dre:true},
 {id:'fc_clean',name:'Material de limpeza',kind:'expense',dre:true},
 {id:'fc_office',name:'Material de escritório',kind:'expense',dre:true},
 {id:'fc_maint',name:'Manutenção emergencial',kind:'expense',dre:true},
 {id:'fc_transport',name:'Transporte',kind:'expense',dre:true},
 {id:'fc_small',name:'Pequenas compras',kind:'expense',dre:true},
 {id:'fc_other_expense',name:'Outros',kind:'expense',dre:true},
 {id:'fc_advance',name:'Adiantamento a colaborador',kind:'asset',dre:false},
 {id:'fc_transfer',name:'Transferência entre contas',kind:'transfer',dre:false},
 {id:'fc_signal',name:'Sinais / créditos recebidos',kind:'liability',dre:false},
 {id:'fc_tip',name:'Gorjetas a repassar',kind:'liability',dre:false}
];
if(!Array.isArray(db.companyEntities))db.companyEntities=[
 {id:'cnpj1',name:'Império — Big Shopping',unitId:'u1',cnpj:'',active:true},
 {id:'cnpj2',name:'Império — Shopping Contagem',unitId:'u2',cnpj:'',active:true},
 {id:'cnpj3',name:'Império — Centro de Contagem',unitId:'u3',cnpj:'',active:true}
];
if(!Array.isArray(db.financeGoals))db.financeGoals=[];
function financeSubnav(){let tabs=[['entries','Lançamentos'],['accounts','Contas'],['dre','DRE'],['goals','Metas'],['payments','Formas de pagamento'],['cnpjs','CNPJs'],['invoices','Notas fiscais']];return `<div class="finance-subnav">${tabs.map(([id,n])=>`<button class="${financeTab===id?'active':''}" onclick="setFinanceTab('${id}')">${n}</button>`).join('')}</div>`}
function setFinanceTab(t){financeTab=t;renderFinance()}
function financeUnitId(){let id=document.getElementById('unitPicker')?.value||'';return (db.units||[]).some(u=>u.id===id&&u.active!==false)?id:''}
function financeUnitLabel(id){return db.units.find(u=>u.id===id)?.name||'—'}
function financeAccountByName(name){return (db.financialAccounts||[]).find(a=>a.name===name)}
function financeEntryCategory(e){
 if(e.category)return e.category;
 let n=String(e.nature||'').toLowerCase();
 if(n.includes('sinal')||n.includes('crédito')||n.includes('credito'))return 'Sinais / créditos recebidos';
 if(n.includes('adiantamento'))return 'Adiantamento a colaborador';
 if(n.includes('transfer'))return 'Transferência entre contas';
 if(n.includes('gorjeta'))return 'Gorjetas a repassar';
 if(Number(e.amount||0)<0)return 'Outros';
 return 'Recebimentos';
}
function financeEntryDreImpact(e){if(e.dreImpact===false)return false;let n=String(e.nature||'').toLowerCase();if(n.includes('sinal')||n.includes('crédito')||n.includes('credito')||n.includes('adiantamento')||n.includes('transfer')||n.includes('gorjeta'))return false;return Number(e.amount||0)<0}
function financeSyntheticEntries(){
 let out=(db.demoFinancialEntries||[]).map(e=>({...e,_source:'ledger'}));
 // Histórico anterior à ativação do Financeiro: mostra comandas antigas sem duplicar comandas já lançadas.
 for(const c of (db.clientCommands||[]).filter(x=>x.status==='Pago')){
   let code=String(c.id).replace(/\D/g,'');
   let exists=out.some(e=>String(e.origin||'').includes(code)||e.commandId===c.id);
   if(!exists)out.push({id:'hist_'+c.id,unitId:c.unitId,date:c.date,amount:Number(c.total||0),nature:'Recebimento de comanda',category:'Receita de serviços',account:'Histórico importado',origin:`Comanda #${code}`,dreImpact:false,_source:'history'});
 }
 return out.sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));
}
function financeFiltersState(){return {from:document.getElementById('finFrom')?.value||financeMonthStart,to:document.getElementById('finTo')?.value||financeToday,unit:document.getElementById('finUnit')?.value||financeUnitId(),account:document.getElementById('finAccount')?.value||'',q:(document.getElementById('finSearch')?.value||'').trim().toLowerCase()}}
function financeFilteredEntries(state=financeFiltersState()){
 return financeSyntheticEntries().filter(e=>{
   if(state.from&&String(e.date||'')<state.from)return false;if(state.to&&String(e.date||'')>state.to)return false;
   if(state.unit&&state.unit!=='all'&&e.unitId!==state.unit)return false;
   if(state.account&&e.account!==state.account)return false;
   if(state.q&&!`${e.nature||''} ${e.category||''} ${e.account||''} ${e.origin||''} ${e.professionalName||''}`.toLowerCase().includes(state.q))return false;
   return true;
 })
}
function financeProcessorFees(entries){return entries.reduce((s,e)=>s+Math.max(0,Number(e.processorFee||0)),0)}
function financeKpis(entries){let incoming=0,outgoing=0,pendingIn=0,pendingOut=0;for(const e of entries){let a=Number(e.amount||0);if(e.status==='Previsto'){if(a>=0)pendingIn+=a;else pendingOut+=Math.abs(a)}else if(a>=0)incoming+=a;else outgoing+=Math.abs(a)}return {incoming,outgoing,net:incoming-outgoing,pendingIn,pendingOut,fees:financeProcessorFees(entries)}}
function financeFilterHtml(){let uid=financeUnitId(),accounts=(db.financialAccounts||[]).filter(a=>a.unitId===uid);return `<div class="finance-filters"><div class="field"><label>De</label><input id="finFrom" type="date" value="${financeMonthStart}" onchange="renderFinanceEntriesBody()"></div><div class="field"><label>Até</label><input id="finTo" type="date" value="${financeToday}" onchange="renderFinanceEntriesBody()"></div><div class="field"><label>Unidade</label><select id="finUnit" onchange="renderFinanceEntriesBody()"><option value="all">Todas</option>${db.units.filter(u=>u.active!==false).map(u=>`<option value="${u.id}" ${u.id===uid?'selected':''}>${escapeHtml(u.name)}</option>`).join('')}</select></div><div class="field"><label>Conta</label><select id="finAccount" onchange="renderFinanceEntriesBody()"><option value="">Todas</option>${accounts.map(a=>`<option>${escapeHtml(a.name)}</option>`).join('')}</select></div><div class="field" style="flex:1"><label>Buscar</label><input id="finSearch" style="width:100%" placeholder="Categoria, origem, conta..." oninput="renderFinanceEntriesBody()"></div></div>`}
function renderFinance(){subbar.innerHTML=financeSubnav();if(financeTab==='entries')return renderFinanceEntries();if(financeTab==='accounts')return renderFinanceAccounts();if(financeTab==='dre')return renderFinanceDre();if(financeTab==='payments')return renderFinancePayments();if(financeTab==='goals')return renderFinanceGoals();if(financeTab==='cnpjs')return renderFinanceCnpjs();return renderFinanceInvoices()}
function renderFinanceEntries(){adminPage.innerHTML=`<div class="page-head"><div><h1>Financeiro</h1><div class="muted">Fluxo financeiro consolidado de Caixa, comandas, sinais, sangrias e lançamentos manuais.</div></div><div class="spacer"></div><button class="btn btn-primary" onclick="openFinanceEntry()">+ Novo lançamento</button></div>${financeFilterHtml()}<div id="financeEntriesBody"></div>`;renderFinanceEntriesBody()}
function renderFinanceEntriesBody(){let host=document.getElementById('financeEntriesBody');if(!host)return;let es=financeFilteredEntries(),k=financeKpis(es);host.innerHTML=`<div class="finance-kpis"><div class="finance-kpi positive"><span>Entradas efetivadas</span><b>${money(k.incoming)}</b></div><div class="finance-kpi negative"><span>Saídas efetivadas</span><b>${money(k.outgoing)}</b></div><div class="finance-kpi emphasis"><span>Movimento líquido</span><b>${money(k.net)}</b></div><div class="finance-kpi"><span>A receber</span><b>${money(k.pendingIn)}</b></div><div class="finance-kpi"><span>A pagar</span><b>${money(k.pendingOut)}</b></div></div><div class="inline-note" style="margin-bottom:12px"><b>Uma fonte de verdade:</b> lançamentos originados no Caixa/Comanda aparecem aqui automaticamente. Transferências, sinais, gorjetas e adiantamentos permanecem separados para não distorcer o DRE.</div><div class="table-card"><table class="table"><thead><tr><th>Data</th><th>Natureza</th><th>Categoria</th><th>Unidade</th><th>Conta</th><th>Origem</th><th>Impacto DRE</th><th>Valor</th></tr></thead><tbody>${es.length?es.map(e=>`<tr><td>${formatDateBR(e.date)}</td><td><b>${escapeHtml(e.nature||'Lançamento')}</b></td><td>${escapeHtml(financeEntryCategory(e))}</td><td>${escapeHtml(financeUnitLabel(e.unitId))}</td><td>${escapeHtml(e.account||'—')}</td><td>${escapeHtml(e.origin||e.supplier||'—')}</td><td><span class="finance-tag ${financeEntryDreImpact(e)?'dre':'nondre'}">${financeEntryDreImpact(e)?'Sim':'Não'}</span></td><td class="${Number(e.amount||0)>=0?'finance-entry-positive':'finance-entry-negative'}">${Number(e.amount||0)>=0?'+ ':''}${money(Number(e.amount||0))}</td></tr>`).join(''):`<tr><td colspan="8" class="finance-empty">Nenhum lançamento neste período.</td></tr>`}</tbody></table></div>`}
function financeEntryAccountOptions(unitId){return (db.financialAccounts||[]).filter(a=>a.unitId===unitId).map(a=>`<option value="${a.id}">${escapeHtml(a.name)}</option>`).join('')}
function refreshFinanceEntryAccounts(){let u=document.getElementById('finEntryUnit')?.value||financeUnitId(),el=document.getElementById('finEntryAccount');if(el)el.innerHTML=financeEntryAccountOptions(u)}
function openFinanceEntry(){let uid=financeUnitId();modal('Novo lançamento financeiro',`<div class="inline-note" style="margin-bottom:12px">Use para lançamentos que não nasceram de Comanda/Caixa. Se a movimentação saiu do caixa físico, prefira registrar pela própria aba <b>Caixa → Sangria/Suprimento</b>, para manter a conciliação.</div><div class="form-grid"><div class="field"><label>Tipo</label><select id="finEntryDirection" onchange="refreshFinanceCategoryOptions()"><option value="income">Entrada</option><option value="expense">Saída / despesa</option></select></div><div class="field"><label>Status</label><select id="finEntryStatus"><option>Efetivado</option><option>Previsto</option></select></div><div class="field"><label>Data</label><input id="finEntryDate" type="date" value="${financeToday}"></div><div class="field"><label>Unidade</label><select id="finEntryUnit" onchange="refreshFinanceEntryAccounts()">${db.units.filter(u=>u.active!==false).map(u=>`<option value="${u.id}" ${u.id===uid?'selected':''}>${escapeHtml(u.name)}</option>`).join('')}</select></div><div class="field"><label>Conta</label><select id="finEntryAccount">${financeEntryAccountOptions(uid)}</select></div><div class="field"><label>Categoria / DRE</label><select id="finEntryCategory"></select></div><div class="field full"><label>Descrição / origem</label><input id="finEntryDesc" placeholder="Ex.: compra de material / receita eventual"></div><div class="field"><label>Valor</label><input id="finEntryAmount" type="number" min="0.01" step="0.01" placeholder="0,00"></div></div>`,`<button class="btn btn-ghost" onclick="closeModal()">Cancelar</button><button class="btn btn-primary" onclick="saveFinanceEntry()">Salvar lançamento</button>`);refreshFinanceCategoryOptions()}
function refreshFinanceCategoryOptions(){let dir=document.getElementById('finEntryDirection')?.value||'income',el=document.getElementById('finEntryCategory');if(!el)return;let rows=db.financeCategories.filter(c=>dir==='income'?c.kind==='income':c.kind==='expense');el.innerHTML=rows.map(c=>`<option value="${c.id}">${escapeHtml(c.name)}</option>`).join('')}
function saveFinanceEntry(){let dir=document.getElementById('finEntryDirection')?.value||'income',amount=Math.max(0,Number(document.getElementById('finEntryAmount')?.value||0));if(!(amount>0)){toast('Informe um valor válido');return}let unitId=document.getElementById('finEntryUnit')?.value||financeUnitId(),accId=document.getElementById('finEntryAccount')?.value||'',acc=db.financialAccounts.find(a=>a.id===accId),cat=db.financeCategories.find(c=>c.id===document.getElementById('finEntryCategory')?.value),status=document.getElementById('finEntryStatus')?.value||'Efetivado',date=document.getElementById('finEntryDate')?.value||financeToday,desc=document.getElementById('finEntryDesc')?.value.trim()||'Lançamento manual';db.demoFinancialEntries.push({id:'fe_manual_'+Date.now(),unitId,date,amount:dir==='expense'?-amount:amount,nature:dir==='expense'?'Despesa manual':'Receita manual',category:cat?.name||'Outros',account:acc?.name||'',origin:desc,dreImpact:cat?.dre!==false,status,createdBy:currentUserName(),createdAt:new Date().toISOString()});save();closeModal();renderFinance();toast('Lançamento financeiro salvo ✓')}
function financeAccountBalanceLegacySynthetic(a){let name=a.name;return financeSyntheticEntries().filter(e=>e.account===name&&e.status!=='Previsto').reduce((s,e)=>s+Number(e.amount||0),0)}
function renderFinanceAccounts(){let uid=financeUnitId(),rows=(db.financialAccounts||[]).filter(a=>a.unitId===uid);adminPage.innerHTML=`<div class="page-head"><div><h1>Contas e destinos</h1><div class="muted">Vincule cada conta às formas de pagamento aceitas e às taxas da operadora.</div></div></div><div class="inline-note" style="margin-bottom:14px"><b>Exemplo:</b> Dinheiro → somente Caixa físico. Pix → contas bancárias habilitadas. Débito/Crédito → adquirentes habilitadas. A Comanda usa esta configuração para filtrar os destinos automaticamente.</div><div class="finance-account-grid">${rows.map(a=>{let methods=(a.paymentMethodIds||[]).map(id=>db.paymentMethods.find(m=>m.id===id)?.name).filter(Boolean);return `<div class="finance-account-card"><span class="finance-tag">${a.type==='CASH'?'Caixa físico':a.type==='BANK'?'Banco':'Operadora'}</span><h3>${escapeHtml(a.name)}</h3><div class="muted">${escapeHtml(financeUnitLabel(a.unitId))}</div><div class="balance">${money(financeAccountBalance(a))}</div><div class="muted" style="font-size:11px">movimento líquido registrado</div><div class="finance-methods">${methods.map(x=>`<span>${escapeHtml(x)}</span>`).join('')||'<span>Nenhuma forma vinculada</span>'}</div><button class="btn btn-ghost btn-sm" style="margin-top:12px" onclick="openFinanceAccount('${a.id}')">Configurar</button></div>`}).join('')}</div>`}
function openFinanceAccount(id){let a=db.financialAccounts.find(x=>x.id===id);if(!a)return;let methods=db.paymentMethods.filter(m=>!['pm_direct','pm_barter'].includes(m.id));modal('Configurar conta / destino',`<div class="form-grid"><div class="field full"><label>Nome</label><input id="finAccName" value="${escapeAttr(a.name)}"></div><div class="field"><label>Tipo</label><select id="finAccType"><option value="CASH" ${a.type==='CASH'?'selected':''}>Caixa físico</option><option value="BANK" ${a.type==='BANK'?'selected':''}>Conta bancária</option><option value="PROCESSOR" ${a.type==='PROCESSOR'?'selected':''}>Operadora / adquirente</option></select></div><div class="field"><label>Unidade</label><input value="${escapeAttr(financeUnitLabel(a.unitId))}" disabled></div><div class="field full"><label>Formas de pagamento aceitas</label><div class="combo-service-list">${methods.map(m=>`<label class="combo-service-option"><input class="fin-acc-method" type="checkbox" value="${m.id}" ${(a.paymentMethodIds||[]).includes(m.id)?'checked':''}><span><b>${escapeHtml(m.name)}</b></span></label>`).join('')}</div></div><div class="field"><label>Taxa Débito (%)</label><input id="finFeeDebit" type="number" min="0" step="0.01" value="${Number(a.feeRules?.pm_debit?.percent||0)}"></div><div class="field"><label>Taxa Crédito (%)</label><input id="finFeeCredit" type="number" min="0" step="0.01" value="${Number(a.feeRules?.pm_credit?.percent||0)}"></div></div><div class="inline-note" style="margin-top:12px">Essas taxas serão calculadas automaticamente na finalização da Comanda e aparecerão no Financeiro/DRE, sem poluir a tela da recepção.</div>`,`<button class="btn btn-ghost" onclick="closeModal()">Cancelar</button><button class="btn btn-primary" onclick="saveFinanceAccount('${id}')">Salvar</button>`)}
function saveFinanceAccount(id){let a=db.financialAccounts.find(x=>x.id===id);if(!a)return;a.name=document.getElementById('finAccName')?.value.trim()||a.name;a.type=document.getElementById('finAccType')?.value||a.type;a.paymentMethodIds=[...document.querySelectorAll('.fin-acc-method:checked')].map(x=>x.value);a.feeRules=a.feeRules||{};a.feeRules.pm_debit={percent:Math.max(0,Number(document.getElementById('finFeeDebit')?.value||0))};a.feeRules.pm_credit={percent:Math.max(0,Number(document.getElementById('finFeeCredit')?.value||0))};save();closeModal();renderFinanceAccounts();toast('Conta financeira atualizada ✓')}
function financeDrePeriod(){let from=document.getElementById('dreFrom')?.value||financeMonthStart,to=document.getElementById('dreTo')?.value||financeToday,unit=document.getElementById('dreUnit')?.value||financeUnitId();return {from,to,unit}}
function financeDreData(st=financeDrePeriod()){
 let cmds=(db.clientCommands||[]).filter(c=>c.status==='Pago'&&c.date>=st.from&&c.date<=st.to&&(st.unit==='all'||c.unitId===st.unit));
 let serviceRevenue=cmds.reduce((s,c)=>s+Number(c.total||0),0);
 let customerFees=cmds.reduce((s,c)=>s+Number(c.customerFee||0),0);
 let processorFees=(db.demoCashMovements||[]).filter(m=>m.date>=st.from&&m.date<=st.to&&(st.unit==='all'||m.unitId===st.unit)).reduce((s,m)=>s+Number(m.processorFee||0),0);
 let expenses=financeSyntheticEntries().filter(e=>e.date>=st.from&&e.date<=st.to&&(st.unit==='all'||e.unitId===st.unit)&&Number(e.amount||0)<0&&financeEntryDreImpact(e));
 let expenseTotal=expenses.reduce((s,e)=>s+Math.abs(Number(e.amount||0)),0);
 let tips=(db.tipMovements||[]).filter(t=>t.date>=st.from&&t.date<=st.to&&(st.unit==='all'||t.unitId===st.unit)).reduce((s,t)=>s+Number(t.gross||0),0);
 return {serviceRevenue,customerFees,processorFees,expenses,expenseTotal,tips,result:serviceRevenue+customerFees-processorFees-expenseTotal};
}
function renderFinanceDre(){let uid=financeUnitId();adminPage.innerHTML=`<div class="page-head"><div><h1>DRE gerencial</h1><div class="muted">Visão por competência operacional. Sinais, créditos, transferências, vales e gorjetas não entram como receita/despesa de serviço.</div></div></div><div class="finance-filters"><div class="field"><label>De</label><input id="dreFrom" type="date" value="${financeMonthStart}" onchange="renderFinanceDreBody()"></div><div class="field"><label>Até</label><input id="dreTo" type="date" value="${financeToday}" onchange="renderFinanceDreBody()"></div><div class="field"><label>Unidade</label><select id="dreUnit" onchange="renderFinanceDreBody()"><option value="all">Todas</option>${db.units.filter(u=>u.active!==false).map(u=>`<option value="${u.id}" ${u.id===uid?'selected':''}>${escapeHtml(u.name)}</option>`).join('')}</select></div></div><div id="financeDreBody"></div>`;renderFinanceDreBody()}
function renderFinanceDreBody(){let host=document.getElementById('financeDreBody');if(!host)return;let d=financeDreData();let byCat={};for(const e of d.expenses){let k=financeEntryCategory(e);byCat[k]=(byCat[k]||0)+Math.abs(Number(e.amount||0))}host.innerHTML=`<div class="dre-card"><div class="dre-row"><span>Receita de serviços realizada</span><b>${money(d.serviceRevenue)}</b></div>${d.customerFees?`<div class="dre-row"><span>Acréscimos cobrados da cliente</span><b>${money(d.customerFees)}</b></div>`:''}<div class="dre-row"><span>(−) Taxas de operadora</span><b>${money(d.processorFees)}</b></div>${Object.entries(byCat).map(([k,v])=>`<div class="dre-row indent"><span>(−) ${escapeHtml(k)}</span><b>${money(v)}</b></div>`).join('')}<div class="dre-row total"><span>Total de despesas operacionais lançadas</span><b>${money(d.expenseTotal)}</b></div><div class="dre-row result"><span>Resultado gerencial parcial</span><b>${money(d.result)}</b></div></div><div class="inline-note" style="max-width:860px;margin-top:12px"><b>Parcial nesta etapa:</b> ainda vamos incluir comissões, insumos/CMV, custos fixos, impostos e demais despesas para chegar ao resultado gerencial completo. Gorjetas recebidas (${money(d.tips)}) ficam fora da receita porque pertencem à profissional.</div>`}
function renderFinancePayments(){let rows=(db.paymentMethods||[]).filter(m=>!['pm_direct','pm_barter'].includes(m.id));adminPage.innerHTML=`<div class="page-head"><div><h1>Formas de pagamento</h1><div class="muted">Veja em quais contas cada forma pode ser recebida.</div></div></div><div class="table-card"><table class="table"><thead><tr><th>Forma</th><th>Contas habilitadas</th><th>Regra</th></tr></thead><tbody>${rows.map(m=>{let as=(db.financialAccounts||[]).filter(a=>(a.paymentMethodIds||[]).includes(m.id));return `<tr><td><b>${escapeHtml(m.name)}</b></td><td>${as.map(a=>escapeHtml(a.name)).join('<br>')||'—'}</td><td>${m.id==='pm_cash'?'Somente caixa físico':m.id==='pm_pix'?'Contas bancárias habilitadas':'Operadoras/adquirentes habilitadas'}</td></tr>`}).join('')}</tbody></table></div><div class="inline-note" style="margin-top:12px">A configuração prática é feita em <b>Contas</b>. Isso mantém a finalização da Comanda rápida e evita selecionar um destino incompatível.</div>`}
function renderFinanceGoals(){let uid=financeUnitId(),goal=(db.financeGoals||[]).find(g=>g.unitId===uid&&g.month===financeToday.slice(0,7));adminPage.innerHTML=`<div class="page-head"><div><h1>Metas financeiras</h1><div class="muted">Primeira estrutura para meta mensal por unidade.</div></div><div class="spacer"></div><button class="btn btn-primary" onclick="openFinanceGoal()">Definir meta</button></div><div class="card" style="max-width:620px"><div class="muted">${escapeHtml(financeUnitLabel(uid))} · ${financeToday.slice(0,7)}</div><div style="font-size:34px;font-weight:900;margin:8px 0">${goal?money(goal.amount):'Meta ainda não definida'}</div><div class="muted">Depois conectaremos esta meta ao Dashboard com valor realizado, restante, dias operacionais e média diária necessária.</div></div>`}
function openFinanceGoal(){let uid=financeUnitId(),month=financeToday.slice(0,7),g=(db.financeGoals||[]).find(x=>x.unitId===uid&&x.month===month);modal('Meta mensal',`<div class="field"><label>Unidade</label><input value="${escapeAttr(financeUnitLabel(uid))}" disabled></div><div class="field" style="margin-top:12px"><label>Mês</label><input value="${month}" disabled></div><div class="field" style="margin-top:12px"><label>Meta de faturamento</label><input id="finGoalAmount" type="number" min="0" step="0.01" value="${Number(g?.amount||0)}"></div>`,`<button class="btn btn-ghost" onclick="closeModal()">Cancelar</button><button class="btn btn-primary" onclick="saveFinanceGoal()">Salvar meta</button>`)}
function saveFinanceGoal(){let uid=financeUnitId(),month=financeToday.slice(0,7),amount=Math.max(0,Number(document.getElementById('finGoalAmount')?.value||0)),g=db.financeGoals.find(x=>x.unitId===uid&&x.month===month);if(!g){g={id:'fg'+Date.now(),unitId:uid,month};db.financeGoals.push(g)}g.amount=amount;save();closeModal();renderFinanceGoals();toast('Meta salva ✓')}
function renderFinanceCnpjs(){adminPage.innerHTML=`<div class="page-head"><div><h1>CNPJs / empresas</h1><div class="muted">Estrutura que depois será usada em contas, notas fiscais e relatórios por empresa.</div></div></div><div class="table-card"><table class="table"><thead><tr><th>Empresa</th><th>Unidade</th><th>CNPJ</th><th>Status</th></tr></thead><tbody>${db.companyEntities.map(x=>`<tr><td><b>${escapeHtml(x.name)}</b></td><td>${escapeHtml(financeUnitLabel(x.unitId))}</td><td>${escapeHtml(x.cnpj||'A preencher')}</td><td>${x.active?'Ativo':'Inativo'}</td></tr>`).join('')}</tbody></table></div>`}
function renderFinanceInvoices(){adminPage.innerHTML=`<div class="page-head"><div><h1>Notas fiscais</h1><div class="muted">Estrutura reservada para emissão assíncrona por comanda.</div></div></div><div class="card" style="max-width:760px"><span class="pill">Próxima etapa fiscal</span><h3 style="margin-top:12px">A emissão será vinculada à comanda</h3><p class="muted">Cada documento terá CNPJ emissor, comanda, status, chave, XML/PDF e tentativas. Falhas poderão ser reenviadas sem duplicar a nota.</p></div>`}
const _renderAdminV31=renderAdmin;
renderAdmin=function(){if(page==='finance')return renderFinance();return _renderAdminV31()};

